return [ 'project-id-version' => 'fluid-checkout','mime-version' => '1.0','content-type' => 'text/plain; charset=utf-8','content-transfer-encoding' => '8bit','language-team' => 'Fluid Checkout','last-translator' => 'Fluid Checkout','pot-creation-date' => '2025-03-05 23:46+0000','report-msgid-bugs-to' => 'https://fluidcheckout.com/support','x-poedit-basepath' => '..','x-poedit-keywordslist' => '__;_e;_ex:1,2c;_n:1,2;_n_noop:1,2;_nx:1,2,4c;_nx_noop:1,2,3c;_x:1,2c;esc_attr__;esc_attr_e;esc_attr_x:1,2c;esc_html__;esc_html_e;esc_html_x:1,2c','x-poedit-searchpath-0' => '.','x-poedit-searchpathexcluded-0' => '*.js','x-poedit-sourcecharset' => 'UTF-8','plural-forms' => 'nplurals=2; plural=(n != 1);','messages' => ['WooCommerce' => 'WooCommerce','Go to Plugin Search' => 'עבור אל חיפוש תוספים','Activate %s' => 'הפעל את %s','<strong>%1$s</strong> requires <strong>%2$s</strong> to be installed and activated. <a href="%4$s">%3$s</a>' => '<strong>%1$s</strong> דורש התקנה והפעלה של <strong>%2$s</strong> . <a href="%4$s">%3$s</a>','Enter your code here' => 'הזן את הקוד שלך כאן','Add %s' => 'הוסף %s','Remove' => 'לְהַסִיר','Order number and receipt will be sent to this email address.' => 'מספר הזמנה וקבלה יישלחו לכתובת דוא&quot;ל זו.','Apartment, unit, building, floor, etc.' => 'דירה, יחידה, בניין, קומה וכו&#39;.','Shipping phone' => 'טלפון למשלוח','Only used for shipping-related questions.' => 'משמש רק לשאלות הקשורות למשלוח.','Single step' => 'צעד בודד','Click to go to the order summary' => 'לחץ למעבר לסיכום ההזמנה','Cart total:' => 'סה&quot;כ עגלה:','Proceed to %s' => 'המשך אל %s','Proceed to contact' => 'המשך ליצירת קשר','Proceed to shipping' => 'המשך למשלוח','Proceed to billing' => 'המשך לחיוב','Proceed to payment' => 'המשך לתשלום','Shipping method' => 'שיטת משלוח','Additional notes' => 'הערות נוספות','Payment method' => 'אמצעי תשלום','Step %1$s of %2$s' => 'שלב %1$s מתוך %2$s','Change: %s' => 'שינוי: %s','Not selected yet.' => 'עדיין לא נבחר.','Same as shipping address' => 'זהה לכתובת למשלוח','Same as billing address' => 'זהה לכתובת לחיוב','Order summary' => 'סיכום הזמנה','Edit cart' => 'ערוך עגלה','Did you mean %s?' => 'האם התכוונת ל-%s?','Change email address to: {suggestion-value}' => 'שנה את כתובת האימייל ל: {suggestion-value}','This is a required field.' => 'זהו שדה חובה.','This is not a valid email address.' => 'זו אינה כתובת אימייל חוקית.','This field does not match the related field value.' => 'שדה זה אינו תואם לערך השדה הקשור.','The CPF number "{cpf_number}" is invalid.' => 'מספר ה-CPF &quot;{cpf_number}&quot; אינו חוקי.','The CNPJ number "{cnpj_number}" is invalid.' => 'מספר ה-CNPJ &quot;{cnpj_number}&quot; אינו חוקי.','(Required)' => '(דָרוּשׁ)','Checkout Header - Desktop' => 'Checkout Header - שולחן עבודה','Display widgets on the checkout header for large screens. Only displayed if using the plugin\'s checkout header.' => 'הצג ווידג&#39;טים בכותרת התשלום עבור מסכים גדולים. מוצג רק אם משתמשים בכותרת התשלום של התוסף.','Checkout Header - Mobile' => 'Checkout Header - נייד','Display widgets below the checkout header for mobile devices. Only displayed if using the plugin\'s checkout header.' => 'הצג ווידג&#39;טים מתחת לכותרת התשלום עבור מכשירים ניידים. מוצג רק אם משתמשים בכותרת התשלום של התוסף.','Checkout Sidebar' => 'סרגל הצד של התשלום','Display widgets on the checkout sidebar after the order summary.' => 'הצג ווידג&#39;טים בסרגל הצד של התשלום לאחר סיכום ההזמנה.','Checkout Order Summary' => 'סיכום הזמנות לקופה','Display widgets inside the order summary at the checkout page.' => 'הצג ווידג&#39;טים בתוך סיכום ההזמנה בעמוד התשלום.','Checkout Below Place Order' => 'קופה מתחת בצע הזמנה','Display widgets below the place order button at the checkout page.' => 'הצג ווידג&#39;טים מתחת לכפתור ההזמנה בדף התשלום.','Checkout Footer' => 'כותרת תחתונה לקופה','Display widgets on the checkout footer. Only displayed if using the plugin\'s checkout footer.' => 'הצג ווידג&#39;טים בכותרת התחתונה של התשלום. מוצג רק אם משתמשים בכותרת התחתונה של התוסף.','Classic' => 'קלַאסִי','Boxed' => 'בקופסא','Split' => 'לְפַצֵל','Minimalist' => 'מינימליסטי','Fluid Checkout and Delivery Date plugins by CodeRockz' => 'פלאגין Fluid Checkout ותאריך אספקה מאת CodeRockz','<p>We detected that you are using the plugins Delivery & Pickup Date Time for WooCommerce (free and PRO) by CodeRockz. Integration with these plugins have been moved to Fluid Checkout PRO.</p>' => '<p style=";text-align:right;direction:rtl">זיהינו שאתה משתמש בתוספים תאריך מסירה ואיסוף זמן עבור WooCommerce (חינם ו-PRO) של CodeRockz. האינטגרציה עם התוספים הללו הועברה ל- Fluid Checkout PRO.</p>','Upgrade to PRO' => 'שדרג ל-PRO','Fluid Checkout database updated successfully' => 'מסד הנתונים של Fluid Checkout עודכן בהצלחה','The database changes where applied successfully.' => 'מסד הנתונים משתנה כאשר הוחל בהצלחה.','Dismiss' => 'לְפַטֵר','Fluid Checkout database update' => 'עדכון מסד הנתונים של Fluid Checkout','Some changes to the database are required. As with any update, we recommend you to <strong>take a full backup of your website before proceeding</strong>.' => 'נדרשים כמה שינויים במסד הנתונים. כמו בכל עדכון, אנו ממליצים לך <strong>לבצע גיבוי מלא של האתר שלך לפני שתמשיך</strong> .','Update database' => 'עדכון מסד נתונים','Fluid Checkout is not compatible with the Divi Builder checkout layout' => 'Fluid Checkout אינו תואם לפריסת התשלום של Divi Builder','<p>Fluid Checkout needs the classic WooCommerce shortcode-based checkout form to work. When using the Divi Builder to customize the look and feel of the checkout page, the classic shortcodes are replaced with custom widgets from the Divi Builder for each part of the checkout page. These custom widgets are not compatible with Fluid Checkout.</p><p>Please edit your checkout page replacing the Divi Builder widgets with the a text widget containing the shortcode <code>[woocommerce_checkout]</code>.</p>' => '<p style=";text-align:right;direction:rtl">Fluid Checkout צריך את טופס התשלום הקלאסי מבוסס WooCommerce Shortcode כדי לעבוד. כאשר משתמשים ב- Divi Builder כדי להתאים אישית את המראה והתחושה של עמוד התשלום, הקודים הקצרים הקלאסיים מוחלפים בווידג&#39;טים מותאמים אישית מה- Divi Builder עבור כל חלק בעמוד התשלום. ווידג&#39;טים מותאמים אישית אלה אינם תואמים ל- Fluid Checkout.</p><p style=";text-align:right;direction:rtl"> אנא ערוך את דף התשלום שלך והחלף את הווידג&#39;טים של Divi Builder בווידג&#39;ט טקסט המכיל את הקוד הקצר <code>[woocommerce_checkout]</code> .</p>','Edit the checkout page' => 'ערוך את דף התשלום','Read the documentation.' => 'קרא את התיעוד.','Germanized PRO multistep checkout feature needs to be disabled when using Fluid Checkout' => 'יש להשבית את תכונת התשלום הרב-שלבי PRO בשימוש ב- Fluid Checkout','When using Fluid Checkout, the multistep feature from the Germanized PRO plugin becomes unnecessary and can cause <strong>critical errors while processing new orders</strong>. Please disable the Germanized PRO multistep checkout feature in the plugin settings.' => 'בעת שימוש ב- Fluid Checkout, התכונה מרובת השלבים מהפלאגין Germanized PRO הופכת למיותרת ועלולה לגרום <strong>לשגיאות קריטיות בזמן עיבוד הזמנות חדשות</strong> . אנא השבת את תכונת התשלום הרב-שלבי של Germanized PRO בהגדרות הפלאגין.','Go to Germanized settings' => 'עבור להגדרות גרמניות','Thanks for choosing Fluid Checkout!' => 'תודה שבחרת ב- Fluid Checkout!','You have been using the plugin for a while now. How do you like it so far? <br>Please give us a quick rating, we appreciate every bit of feedback and it encourages us to keep improving the plugin :)' => 'אתה משתמש בתוסף כבר זמן מה. איך אתה אוהב את זה עד עכשיו?<br> אנא תנו לנו דירוג מהיר, אנו מעריכים כל פיסת משוב וזה מעודד אותנו להמשיך ולשפר את התוסף :)','Rate the plugin' => 'דרג את התוסף','I need help!' => 'אני צריך עזרה!','Some features of WooCommerce Checkout Manager by Quadlayers might not work as expected when using it with Fluid Checkout. Read <a href="%s">our documentation</a> for more information and alternative solutions.' => 'ייתכן שחלק מהתכונות של WooCommerce Checkout Manager של Quadlayers לא יפעלו כצפוי בעת השימוש בו עם Fluid Checkout. קרא <a href="%s">את התיעוד שלנו</a> למידע נוסף ופתרונות חלופיים.','Read documentation' => 'קרא תיעוד','Don\'t show this again' => 'אל תראה את זה שוב','Fluid Checkout PRO' => 'Fluid Checkout PRO','More design templates' => 'תבניות עיצוב נוספות','Optimized cart page' => 'עמוד עגלה מותאם','Optimized order received / thank you page' => 'הזמנה אופטימלית התקבלה / דף תודה','Edit cart contents at checkout page' => 'ערוך את תוכן העגלה בעמוד התשלום','Account matching / user matching' => 'התאמת חשבון / התאמת משתמש','Trust symbols on the cart and thank you pages' => 'אמון בסמלים על העגלה ודפי תודה','More positions for the coupon code on the checkout page' => 'עמדות נוספות לקוד הקופון בעמוד התשלום','International phone numbers' => 'מספרי טלפון בינלאומיים','Gift messages and packing slips' => 'הודעות מתנה ותלושי אריזה','Local pickup and in-store collection' => 'איסוף מקומי ואיסוף בחנות','EU-VAT Assistant' => 'עוזר EU-VAT','I already have it – Hide this offer' => 'כבר יש לי את זה - הסתר את ההצעה הזו','Activated' => 'מוּפעָל','Address book' => 'ספר כתובות','Select an image' => 'בחר תמונה','Cart layout' => 'פריסת עגלה','Cart optimizations' => 'אופטימיזציות של עגלה','Enable cart page optimizations' => 'אפשר אופטימיזציות של דפי עגלה','Header and footer template' => 'תבנית כותרת עליונה ותחתונה','Controls whether to use the distraction free page header and footer or keep the currently active theme\'s header and footer.' => 'שולט אם להשתמש בכותרת העליונה והתחתונה של העמוד ללא הסחות דעת או לשמור את הכותרת העליונה והתחתונה של הנושא הפעיל כרגע.','Distraction free header and footer' => 'כותרת עליונה ותחתונה ללא הסחות דעת','Theme\'s header and footer' => 'הכותרת העליונה והתחתונה של ערכת הנושא','Cart elements' => 'רכיבי עגלה','Make the order summary stay visible on the cart page while scrolling' => 'הפוך את סיכום ההזמנה לגלוי בדף העגלה בזמן הגלילה','Coupon codes' => 'קודי קופון','Hidden' => 'מוּסתָר','Before the cart items section' => 'לפני סעיף פריטי העגלה','Inside the cart items section' => 'בתוך קטע פריטי העגלה','After the cart items section' => 'אחרי סעיף פריטי העגלה','Before the shipping section' => 'לפני סעיף המשלוחים','After the shipping section' => 'אחרי סעיף המשלוחים','Before the order summary' => 'לפני סיכום ההזמנה','Inside the order summary' => 'בתוך סיכום ההזמנה','Before the order totals' => 'לפני שההזמנה מסתכמת','After the order totals' => 'לאחר סיכומי ההזמנה','After the order summary' => 'לאחר סיכום ההזמנה','Shipping' => 'מִשׁלוֹחַ','Select position where to display the shipping costs and calculator on the cart page.' => 'בחר מיקום שבו להציג את עלויות המשלוח ואת המחשבון בדף העגלה.','Display as a cart section' => 'הצג כחלק עגלה','Cross-sells' => 'מכירות צולבות','Select position where to display the cross-sells section on the cart page.' => 'בחר מיקום שבו להציג את קטע מכירות צולבות בדף העגלה.','Before the cart actions' => 'לפני פעולות העגלה','After the cart actions' => 'לאחר פעולות העגלה','Layout of cross-sell items on the cart page.' => 'פריסה של פריטי מכירות צולבות בדף העגלה.','Optimized horizontal cross-sells layout' => 'פריסת מכירות צולבות אופקית אופטימלית','Theme\'s cross-sells layout' => 'פריסת מכירות צולבות של ערכת הנושא','Number of cross-sell items to display on the cart page' => 'מספר פריטי מכירות צולבות להצגה בדף העגלה','Add widget areas to the cart page' => 'הוסף אזורי ווידג&#39;ט לדף העגלה','These widget areas are used to add trust symbols and trust badges on the cart page.' => 'אזורי ווידג&#39;ט אלה משמשים להוספת סמלי אמון ותגי אמון בדף העגלה.','Checkout' => 'קופה','Checkout layout' => 'פריסת קופה','Design template' => 'תבנית עיצוב','Dark mode' => 'מצב כהה','Enable dark mode' => 'הפעל מצב כהה','Logo image' => 'תמונת לוגו','Choose an image to be displayed on the checkout page header. Only applies when using the distraction free header and footer.' => 'בחר תמונה שתוצג בכותרת של דף התשלום. חל רק בעת שימוש בכותרת העליונה והתחתונה ללא הסחות דעת.','Header background color' => 'צבע רקע של כותרת','Choose a background color for the checkout page header. Only applies when using the distraction free header and footer.' => 'בחר צבע רקע לכותרת של דף התשלום. חל רק בעת שימוש בכותרת העליונה והתחתונה ללא הסחות דעת.','HTML color value. ie: #f3f3f3' => 'ערך צבע HTML. כלומר: #f3f3f3','Page background color' => 'צבע רקע העמוד','Choose a background color for the checkout page. Color is applied to the <em>body</em> element.' => 'בחר צבע רקע עבור דף התשלום. צבע מוחל על אלמנט <em>הגוף</em> .','Footer background color' => 'צבע רקע של כותרת תחתונה','Choose a background color for the checkout page footer. Only applies when using the distraction free header and footer.' => 'בחר צבע רקע לכותרת התחתונה של דף התשלום. חל רק בעת שימוש בכותרת העליונה והתחתונה ללא הסחות דעת.','Progress bar' => 'סרגל התקדמות','Display the checkout progress bar when using multi-step checkout layout' => 'הצג את סרגל ההתקדמות של התשלום בעת שימוש בפריסת תשלום מרובה שלבים','Make the checkout progress bar stay visible while scrolling' => 'הפוך את סרגל ההתקדמות של התשלום לגלוי בזמן הגלילה','Express checkout' => 'קופה מהירה','Enable the express checkout section' => 'הפעל את סעיף התשלום המהיר','Displays the express checkout section at checkout when supported payment gateways have this feature enabled.' => 'מציג את קטע התשלום המהיר בקופה כאשר תכונה זו מופעלת בשערי תשלום נתמכים.','Display express checkout buttons in one line for larger screens' => 'הצג כפתורי קופה אקספרס בשורה אחת למסכים גדולים יותר','Ignore additional checkout required fields when paying with a compatible express checkout payment gateway' => 'התעלם משדות חובה נוספים לקופה בעת תשלום עם שער תשלום אקספרס תואם','Make the order summary stay visible while scrolling' => 'הפוך את סיכום ההזמנה לגלוי בזמן הגלילה','Choose a background color for the order summary section.' => 'בחר צבע רקע למקטע סיכום ההזמנה.','Highlight the order totals row in the order summary table' => 'סמן את שורת סיכומי ההזמנות בטבלת סיכום ההזמנות','Most useful when the order summary section does not have a highlighted background color. Might also apply to the Cart, Order Received and View Order pages when using Fluid Checkout PRO.' => 'שימושי ביותר כאשר בקטע סיכום ההזמנה אין צבע רקע מודגש. עשוי לחול גם על דפי העגלה, הזמנה שהתקבלה והצגת הזמנה בעת שימוש ב- Fluid Checkout PRO.','Action link on the order summary at checkout.' => 'קישור פעולה בסיכום ההזמנה בקופה.','Edit cart link' => 'ערוך קישור לעגלה','Cart items count' => 'פריטי העגלה נחשבים','Link to shop page' => 'קישור לדף החנות','Cart items' => 'פריטי עגלה','Hide cart items errors at the checkout page' => 'הסתר שגיאות של פריטי עגלה בדף התשלום','Do not display the cart items errors message at the top of the checkout page. When submitting the checkout form to complete the purchase, these error messages will always be displayed.' => 'אל תציג את הודעת השגיאה של פריטי עגלת הקניות בחלק העליון של דף התשלום. בעת שליחת טופס התשלום להשלמת הרכישה, הודעות השגיאה הללו יוצגו תמיד.','Place order' => 'בצע הזמנה','Define the position to display "Place order" and terms checkbox section.' => 'הגדר את המיקום להצגת &quot;בצע הזמנה&quot; וקטע תיבת הסימון של מונחים.','Some options might not be compatible with some plugins and themes.' => 'ייתכן שחלק מהאפשרויות לא יהיו תואמות עם תוספים וערכות נושא מסוימות.','Below the payment section' => 'מתחת לסעיף התשלום','Below the order summary' => 'מתחת לסיכום ההזמנה','Both below the payment section and the order summary' => 'גם מתחת לסעיף התשלום וגם לסיכום ההזמנה','Add widget areas to the checkout page' => 'הוסף אזורי ווידג&#39;ט לדף התשלום','These widget areas are used to add trust symbols and trust badges on the checkout page.' => 'אזורי ווידג&#39;ט אלה משמשים להוספת סמלי אמון ותגי אמון בדף התשלום.','Display the coupon codes section title' => 'הצג את כותרת הקטע של קודי הקופון','Select position where to display the coupon codes section on the checkout page.' => 'בחר מיקום שבו להציג את קטע קודי הקופון בדף התשלום.','Before the checkout steps' => 'לפני שלבי התשלום','As a substep before payment methods' => 'כצעד משנה לפני אמצעי תשלום','As a substep after payment methods' => 'כצעד משנה לאחר אמצעי תשלום','Default button style' => 'סגנון לחצן ברירת מחדל','"Add" link button' => 'כפתור הקישור &quot;הוסף&quot;.','Checkout fields' => 'שדות קופה','Optional fields' => 'שדות אופציונליים','Hide optional fields behind a link button' => 'הסתר שדות אופציונליים מאחורי כפתור קישור','It is recommended to keep this option checked to reduce the number of open input fields, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#1-address-line-2--company-name-can-safely-be-collapsed-behind-a-link" target="_blank">read the research</a>.' => 'מומלץ להשאיר אפשרות זו מסומנת כדי להפחית את מספר שדות הקלט הפתוחים, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#1-address-line-2--company-name-can-safely-be-collapsed-behind-a-link" target="_blank">קרא את המחקר</a> .','Do not hide "Address line 2" fields behind a link button' => 'אל תסתיר שדות &quot;שורת כתובת 2&quot; מאחורי כפתור קישור','Recommended only when most customers actually need the "Address line 2" field, or when getting the right shipping address is crucial (ie. if delivering food and other perishable products).' => 'מומלץ רק כאשר רוב הלקוחות באמת זקוקים לשדה &quot;שורת כתובת 2&quot;, או כאשר קבלת הכתובת הנכונה למשלוח היא חיונית (כלומר, אם אספקת מזון ומוצרים מתכלים אחרים).','Billing address' => 'כתובת לחיוב','Select position where to display the billing address section on the checkout page.' => 'בחר מיקום שבו להציג את קטע כתובת החיוב בדף התשלום.','As a step before shipping' => 'כשלב לפני המשלוח','As a sub-step before the shipping address section' => 'כשלב משנה לפני סעיף כתובת המשלוח','As a sub-step after the shipping address section' => 'כשלב משנה לאחר סעיף כתובת המשלוח','As a step after shipping' => 'כשלב לאחר המשלוח','As a sub-step before the payment section' => 'כשלב משנה לפני סעיף התשלום','Force billing and shipping addresses to the same (single section)' => 'לכפות כתובות חיוב ומשלוח לאותן (קטע יחיד)','Checkbox for "Same as shipping/billing address" checked by default' => 'תיבת הסימון של &quot;זהה לכתובת למשלוח/חיוב&quot; מסומנת כברירת מחדל','The checkbox "Same as shiping address" will start as checked by default when the shipping address section is displayed first. <br>The checkbox "Same as billing address" will start as checked by default when the billing address section is displayed first. <br> It is recommended to leave this option checked as to significantly reduce the number of open input fields at checkout, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#3-default-billing--shipping-and-hide-the-fields-entirely" target="_blank">read the research</a>.' => 'תיבת הסימון &quot;זהה לכתובת למשלוח&quot; תתחיל כמסומנת כברירת מחדל כאשר קטע כתובת המשלוח יוצג ראשון.<br> תיבת הסימון &quot;זהה לכתובת חיוב&quot; תתחיל כמסומנת כברירת מחדל כאשר קטע הכתובת לחיוב יוצג ראשון.<br> מומלץ להשאיר אפשרות זו מסומנת כדי להפחית משמעותית את מספר שדות הקלט הפתוחים בקופה, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#3-default-billing--shipping-and-hide-the-fields-entirely" target="_blank">קרא את המחקר</a> .','Highlight the billing address section in the checkout form' => 'הדגש את קטע כתובת החיוב בטופס התשלום','Shipping address' => 'כתובת למשלוח','Highlight the shipping address section in the checkout form' => 'הדגש את קטע כתובת המשלוח בטופס התשלום','Shipping methods' => 'שיטות משלוח','Choose in which position to display the shipping methods section.' => 'בחר באיזה מיקום להציג את סעיף שיטות המשלוח.','Before shipping address' => 'לפני כתובת המשלוח','After shipping address' => 'לאחר כתובת למשלוח','Local pickup' => 'איסוף מקומי','Removes shipping address section when a local pickup shipping method is selected.' => 'מסיר את קטע כתובת המשלוח כאשר נבחר שיטת משלוח לאיסוף מקומי.','Replaces the shipping address with the pickup point location when a local pickup shipping method is selected.' => 'מחליף את כתובת המשלוח במיקום נקודת האיסוף כאשר נבחר שיטת משלוח לאיסוף מקומי.','Choose which address to save as the shipping address for local pickup orders.' => 'בחר איזו כתובת לשמור ככתובת למשלוח עבור הזמנות איסוף מקומיות.','Save the selected pickup location' => 'שמור את מיקום האיסוף שנבחר','Save same as the billing address' => 'שמור זהה לכתובת החיוב','Do not save any shipping address' => 'אל תשמור שום כתובת למשלוח','Company name field for shipping address' => 'שדה שם חברה עבור כתובת למשלוח','Change visibility for the company name field for the shipping address section on the checkout form.' => 'שנה את הנראות של שדה שם החברה עבור קטע כתובת המשלוח בטופס התשלום.','If field is set as "optional", which is the default visibility state, no changes will be applied to let other plugins apply any changes they need.' => 'אם השדה מוגדר כ&quot;אופציונלי&quot;, שהוא מצב הנראות המוגדר כברירת מחדל, לא יחולו שינויים כדי לאפשר לפלאגינים אחרים להחיל כל שינוי שהם צריכים.','Hidden (remove field)' => 'מוסתר (הסר שדה)','Optional' => 'אופציונלי','Required' => 'דָרוּשׁ','Add shipping phone field to the checkout form.' => 'הוסף שדה טלפון למשלוח לטופס התשלום.','Choose in which step to display the shipping phone field.' => 'בחר באיזה שלב להציג את שדה הטלפון למשלוח.','Contact step' => 'שלב יצירת קשר','Billing phone' => 'טלפון לחיוב','Add billing phone field to the checkout form.' => 'הוסף שדה טלפון לחיוב לטופס התשלום.','Choose in which step to display the billing phone field.' => 'בחר באיזה שלב להציג את שדה הטלפון לחיוב.','Show country code beside the flag' => 'הצג את קוד המדינה ליד הדגל','Show an example of a valid phone number inside phone fields' => 'הצג דוגמה למספר טלפון חוקי בתוך שדות הטלפון','Do not change placeholders' => 'אל תשנה מצייני מיקום','Show if not defined' => 'הצג אם לא מוגדר','Always show' => 'תמיד להראות','Order notes' => 'הערות להזמנה','Define the visibility of the additional order notes field.' => 'הגדר את הנראות של שדה הערות הזמנה נוספות.','Gift options' => 'אפשרויות מתנה','Allow customers to add a gift message and other gift related options to the order.' => 'אפשר ללקוחות להוסיף הודעת מתנה ואפשרויות אחרות הקשורות למתנה להזמנה.','Display the gift message as part of the order details table instead of a separate section' => 'הצג את הודעת המתנה כחלק מטבלת פרטי ההזמנה במקום קטע נפרד','This option affects the order confirmation page (thank you page) and order details on account pages, emails and packing slips.' => 'אפשרות זו משפיעה על עמוד אישור ההזמנה (דף תודה) ועל פרטי ההזמנה בדפי החשבון, מיילים ותלושי אריזה.','Account matching' => 'התאמת חשבון','Enable the account matching feature' => 'הפעל את תכונת התאמת החשבון','Associate the guest customer\'s orders with their existing account when an account already exists with the customer\'s contact details.' => 'שייך את ההזמנות של הלקוח האורח לחשבון הקיים שלו כאשר כבר קיים חשבון עם פרטי הקשר של הלקוח.','Display message when an account exists with the email address provided' => 'הצג הודעה כאשר קיים חשבון עם כתובת הדוא&quot;ל שסופקה','Replaces the account creation fields with a notification and option to log in. In some contexts, it might be recommended to leave this option disabled to protect the privacy of customers.' => 'מחליף את שדות יצירת החשבון בהודעה ואפשרות להתחבר. בהקשרים מסוימים, ייתכן שמומלץ להשאיר אפשרות זו מושבתת כדי להגן על פרטיות הלקוחות.','Dashboard' => 'לוּחַ מַחווָנִים','Integrations' => 'אינטגרציות','License keys' => 'מפתחות רישיון','Visit our website for more information about our plugins and add-ons.' => 'בקר באתר האינטרנט שלנו למידע נוסף על התוספים והתוספות שלנו.','Order pay page' => 'עמוד תשלום הזמנה','Order pay' => 'להזמין תשלום','Enable order pay page optimizations' => 'אפשר אופטימיזציות של דפי תשלום להזמנה','Changes the layout of order pay page for existing orders pending payment from the customer.' => 'משנה את פריסת דף תשלום ההזמנה עבור הזמנות קיימות בהמתנה לתשלום מהלקוח.','Add widget areas to the order pay page' => 'הוסף אזורי ווידג&#39;ט לעמוד התשלום בהזמנה','These widget areas are used to add trust symbols and trust badges on the order pay page.' => 'אזורי ווידג&#39;טים אלה משמשים להוספת סמלי אמון ותגי אמון בדף תשלום ההזמנה.','Thank you page & order details layout' => 'פריסת עמוד תודה ופרטי הזמנה','Order details optimizations' => 'אופטימיזציות של פרטי הזמנה','Enable thank you page and order details optimizations' => 'אפשר אופטימיזציות של דף תודה ופרטי הזמנה','Changes the layout of order details on the thank you page and account pages.' => 'משנה את פריסת פרטי ההזמנה בעמוד התודה ובדפי החשבון.','Enable order details customizations on email notifications' => 'אפשר התאמות אישיות של פרטי הזמנה בהודעות דוא&quot;ל','Display new sections and change order of sections on email notifications. Styles of order details on email notifications remain unchanged.' => 'הצג קטעים חדשים ושנה את סדר הקטעים בהתראות באימייל. סגנונות פרטי ההזמנה בהתראות בדוא&quot;ל נותרו ללא שינוי.','Thank you page' => 'דף תודה','These options affect the thank you page, also known as order received or order confirmation pages.' => 'אפשרויות אלו משפיעות על עמוד התודה, המכונה גם דפי הזמנה שהתקבלה או אישור הזמנה.','Order details layout' => 'פריסת פרטי הזמנה','Display the order details with wide layout on the thank you page' => 'הצג את פרטי ההזמנה בפריסה רחבה בדף התודה','Add widget areas to the thank you page' => 'הוסף אזורי ווידג&#39;טים לדף התודה','These widget areas are used to add trust symbols and trust badges on the thank you page.' => 'אזורי ווידג&#39;טים אלה משמשים להוספת סמלי אמון ותגי אמון בדף התודה.','Order actions' => 'הזמינו פעולות','Choose in which position to display the order actions.' => 'בחר באיזה מיקום להציג את סדר הפעולות.','Inside the order overview' => 'בתוך סקירת ההזמנה','After the order overview' => 'לאחר סקירת ההזמנה','After order sections' => 'אחרי קטעי הזמנה','Order status' => 'סטטוס הזמנה','Display the order status progress bar' => 'הצג את שורת ההתקדמות של מצב ההזמנה','Choose in which position to display the section.' => 'בחר באיזה מיקום להציג את הקטע.','After the order overview and payment instructions' => 'לאחר סקירת ההזמנה והוראות התשלום','Before the order items section' => 'לפני סעיף הזמנת פריטים','Inside the order items section' => 'בתוך קטע הזמנה של פריטים','After the order items section' => 'לאחר סעיף הזמנת פריטים','On the sidebar' => 'בסרגל הצד','Order downloads' => 'הזמנת הורדות','Gift message' => 'הודעת מתנה','Tools' => 'כְּלֵי עֲבוֹדָה','Troubleshooting' => 'פתרון בעיות','Debug options' => 'אפשרויות ניפוי באגים','Debug mode' => 'מצב ניפוי באגים','Using debug mode affects the website performance. Only use this option while troubleshooting.' => 'שימוש במצב ניפוי באגים משפיע על ביצועי האתר. השתמש באפשרות זו רק בזמן פתרון בעיות.','Load unminified assets' => 'טען נכסים לא ממוינים','Enhanced select fields' => 'שדות בחירה משופרים','Fix automatic zoom-in on form fields' => 'תקן הגדלה אוטומטית של שדות טופס','Set <code>font-size</code> inside form fields to 16px' => 'הגדר <code>font-size</code> בתוך שדות הטופס ל-16 פיקסלים','Fluid Checkout' => 'בדיקת נוזלים','Settings' => 'הגדרות','Support' => 'תְמִיכָה','<a target="_blank" href="%s">Upgrade to PRO</a> to unlock more options.' => '<a target="_blank" href="%s">שדרג ל-PRO</a> כדי לפתוח אפשרויות נוספות.','(PRO)' => '(מִקצוֹעָן)','(experimental)' => '(נִסיוֹנִי)','Please verify your phone number.' => 'נא לאמת את מספר הטלפון שלך.','The Bluehost Plugin' => 'הפלאגין של Bluehost','Custom fields' => 'שדות מותאמים אישית','Enable custom shipping email field' => 'אפשר שדה דוא&quot;ל למשלוח מותאם אישית','When enabled, the shipping email field from the Bluehost plugin will be added to the checkout form.' => 'כאשר מופעל, שדה האימייל למשלוח מהפלאגין Bluehost יתווסף לטופס התשלום.','Captcha Pro by BestWebSoft' => 'Captcha Pro מאת BestWebSoft','Captcha position' => 'עמדת Captcha','Define the position to display the captcha section. Some positions might not work depending on the captcha type chosen.' => 'הגדר את המיקום להצגת קטע ה-captcha. ייתכן שחלק מהעמדות לא יפעלו בהתאם לסוג ה-captcha שנבחר.','Selecting a pickup point is required before proceeding.' => 'יש צורך בבחירת נקודת איסוף לפני שתמשיך.','Pickup point' => 'נקודת איסוף','Pickup point not selected yet.' => 'עדיין לא נבחרה נקודת איסוף.','Pickup point:' => 'נקודת איסוף:','Mailchimp for WooCommerce' => 'Mailchimp עבור WooCommerce','Subscribe checkbox' => 'תיבת סימון הירשם','Override the position for the subscribe checkbox on the checkout page and always display it on the contact step' => 'תעקוף את המיקום של תיבת הסימון של הרשמה בדף התשלום והצג אותה תמיד בשלב יצירת הקשר','Before Shipping Address' => 'לפני כתובת משלוח','(originally "%s")' => '(במקור &quot;%s&quot;)','After Shipping Address' => 'לאחר כתובת למשלוח','Selecting a collection point is required when shipping with FermoPoint.' => 'בחירת נקודת איסוף נדרשת בעת משלוח עם FermoPoint.','If checked informs typos in email to users. (This feature has been disabled because Fluid Checkout offers the feature. Changes to this option will not take effect)' => 'אם מסומן מודיע על שגיאות הקלדה בדוא&quot;ל למשתמשים. (תכונה זו הושבתה כי Fluid Checkout מציעה את התכונה. שינויים באפשרות זו לא ייכנסו לתוקף)','Enable Mail Check: (disabled feature)' => 'אפשר בדיקת דואר: (תכונה מושבתת)','Carrier:' => 'מוֹבִיל:','Sendinblue - WooCommerce Email Marketing' => 'Sendinblue - WooCommerce Email Marketing','Sign up checkbox position' => 'עמדת תיבת הסימון של הרשמה','Move the sign up checkbox to the contact step' => 'העבר את תיבת הסימון של ההרשמה לשלב יצירת הקשר','When enabled, the checkbox will be moved to the contact step independently of the display location defined in the Sendinblue plugin settings.' => 'כאשר היא מופעלת, תיבת הסימון תועבר לשלב איש הקשר ללא תלות במיקום התצוגה שהוגדר בהגדרות התוסף Sendinblue.','Theme Betheme' => 'נושא Betheme','Checkout progress' => 'התקדמות בקופה','Output the checkout steps section from Betheme on the checkout, cart and order received pages.' => 'פלט את קטע שלבי התשלום מ-Betheme בדפי התשלום, העגלה וההזמנה שהתקבלו.','Theme Fennik' => 'נושא פניק','Breadcrumbs' => 'פירורי לחם','Output the breadcrumbs section from the Fennik theme when using Fluid Checkout header and footer.' => 'פלט את קטע פירורי הלחם מהנושא Fennik בעת שימוש בכותרת העליונה והתחתונה של Fluid Checkout.','Theme Go' => 'נושא Go','My account layout' => 'פריסת החשבון שלי','Enable wide layout on "My account" page.' => 'אפשר פריסה רחבה בדף &quot;החשבון שלי&quot;.','Theme Impreza' => 'אימפרזה נושא','Header' => 'כּוֹתֶרֶת','Spacing for site header at the checkout page (in pixels)' => 'מרווח לכותרת האתר בעמוד התשלום (בפיקסלים)','Only applicable when using the Impreza theme header at the checkout page.' => 'חל רק בעת שימוש בכותרת הנושא של Impreza בעמוד התשלום.','Theme Kapee' => 'נושא קאפי','Output the checkout steps section from the Kapee theme on the checkout, cart and order received pages.' => 'פלט את קטע שלבי התשלום מהנושא של Kapee בדפי התשלום, העגלה וההזמנה שהתקבלו.','Theme Porto' => 'נושא פורטו','Output the checkout steps section from the Porto theme on the checkout, cart and order received pages.' => 'פלט את קטע שלבי התשלום מהנושא של פורטו בדפי התשלום, העגלה וההזמנה שהתקבלו.','Theme Pressmart' => 'נושא Pressmart','Output the checkout steps section from the Pressmart theme on the checkout, cart and order received pages.' => 'פלט את קטע שלבי התשלום מתוך ערכת הנושא Pressmart בדפי התשלום, העגלה וההזמנה שהתקבלו.','Theme The Gem' => 'נושא הפנינה','Output the checkout steps section from The Gem theme when using Fluid Checkout header and footer.' => 'פלט את קטע שלבי התשלום מתוך ערכת הנושא Gem בעת שימוש בכותרת העליונה והתחתונה של Fluid Checkout.','Theme Woodmart' => 'נושא וודמארט','Output the checkout steps section from the Woodmart theme when using Fluid Checkout header and footer.' => 'פלט את קטע שלבי התשלום מהערכת נושא של Woodmart בעת שימוש בכותרת העליונה והתחתונה של Fluid Checkout.','Checkout options' => 'אפשרויות קופה','Disable the theme checkout options' => 'השבת את אפשרויות התשלום של הנושא','The options display product image, quantity field, remove button and link to product page added by the theme are disabled by default.' => 'האפשרויות מציגות תמונת מוצר, שדה כמות, כפתור הסרה וקישור לדף המוצר שנוסף על ידי הנושא מושבתות כברירת מחדל.','Theme Atomion' => 'נושא Atomion','Order progress' => 'התקדמות ההזמנה','Display order progress from the theme' => 'הצגת התקדמות ההזמנה מהערכת נושא','Display the form field labels visible on the page' => 'הצג את תוויות שדות הטופס הגלויות בדף','It is recommended to keep this option enabled for a better user experience.' => 'מומלץ להשאיר אפשרות זו מופעלת לחוויית משתמש טובה יותר.','Theme ZK Nito' => 'נושא ZK Nito','Add extra fields to the checkout form' => 'הוסף שדות נוספים לטופס התשלום','Adds an extra shipping email and shipping phone field to the shipping address section.' => 'מוסיף מייל נוסף למשלוח ושדה טלפון למשלוח לקטע כתובת למשלוח.','Go to the home page' => 'עבור לדף הבית','Skip to content' => 'דלג לתוכן','Create an account' => 'צור חשבון','Log in to your account' => 'היכנס לחשבון שלך','Already have an account?' => 'כבר יש לך חשבון?','Logged in as %1$s. <a href="%2$s">Log out</a>' => 'מחובר בתור %1$s. <a href="%2$s">התנתק</a>','Your order has a total amount due of %s. No further payment is needed.' => 'להזמנה שלך יש סכום כולל של %s. אין צורך בתשלום נוסף.','Close and continue with checkout' => 'סגור והמשך בקופה','Continue' => 'לְהַמשִׁיך','Parcel terminal' => 'מסוף חבילות','<p>This widget has been replaced by Fluid Checkout. </p><p>When using Fluid Checkout, the checkout page needs to use the original WooCommerce shortcode <code>[woocommerce_checkout]</code> to work properly.</p><p>For more information, visit the Fluid Checkout documentation.</p>' => '<p style=";text-align:right;direction:rtl">יישומון זה הוחלף על ידי Fluid Checkout.</p><p style=";text-align:right;direction:rtl"> בעת שימוש ב- Fluid Checkout, דף התשלום צריך להשתמש בקוד הקצר המקורי של WooCommerce <code>[woocommerce_checkout]</code> כדי לעבוד כראוי.</p><p style=";text-align:right;direction:rtl"> למידע נוסף, בקר בתיעוד Fluid Checkout.</p>','Theme The7' => 'נושא The7','Additional header sections' => 'קטעי כותרות נוספים','Output additional header sections if enabled in the theme settings.' => 'פלט קטעי כותרת נוספים אם מופעל בהגדרות ערכת הנושא.','More information' => 'מידע נוסף','Pick a Locker' => 'בחר לוקר','Page template' => 'תבנית עמוד','Use `Order confirmation` page template for block-based themes' => 'השתמש בתבנית דף `אישור הזמנה` עבור תבניות מבוססות בלוקים','Only applies when using a block-based theme.' => 'חל רק בעת שימוש בערכת נושא מבוססת בלוקים.','WooCommerce Stripe Gateway' => 'שער ווקומרס סטריפ','Payment form' => 'טופס תשלום','Apply styles to the Stripe payment form fields' => 'החלת סגנונות על שדות טופס התשלום של Stripe','When enabled, Fluid Checkout will apply styles optimized for compatibility with the plugin. You may want to disable this if you are using custom styles for the Stripe payment form fields.' => 'כאשר הוא מופעל, Fluid Checkout יחיל סגנונות המותאמים אישית לתאימות עם התוסף. ייתכן שתרצה להשבית אפשרות זו אם אתה משתמש בסגנונות מותאמים אישית עבור שדות טופס התשלום של Stripe.','Theme Nyture' => 'נושא נייטורה','Output the checkout steps section from the Nyture theme when using Fluid Checkout.' => 'הפקת מקטע שלבי התשלום לערכת נושא Nyture בעת שימוש ב-Fluid Checkout.','Allows customers to make payments for orders that are either created manually by the store admin or not completed during checkout.' => 'מאפשר ללקוחות לבצע תשלומים עבור הזמנות שנוצרו באופן ידני על ידי מנהל החנות או שלא הושלמו במהלך התשלום.','The plugin WooCommerce Checkout Manager by Quadlayers is not compatible with Fluid Checkout' => 'התוסף WooCommerce Checkout Manager של Quadlayers אינו תואם ל-Fluid Checkout','Company name field for billing address' => 'שדה שם חברה עבור כתובת לחיוב','Change visibility for the company name field for the billing address section on the checkout form.' => 'שנה את הנראות של שדה שם החברה עבור מקטע כתובת החיוב בטופס התשלום.','Theme Bookshelf' => 'מדף ספרים נושאי','Output the checkout steps section from the Bookshelf theme when using Fluid Checkout.' => 'פלט את מקטע שלבי התשלום לערכת הנושא Bookshelf בעת שימוש ב-Fluid Checkout.','Account password' => 'סיסמת חשבון','An account will be created with the information provided at checkout when completing the order.' => 'ייווצר חשבון עם המידע שיסופק בעת ביצוע ההזמנה.','Choose the style of the progress bar.' => 'בחר את סגנון סרגל ההתקדמות.','Bars' => 'ברים','Theme Ireca' => 'נושא איריקה','WooCommerce page layout' => 'פריסת עמוד WooCommerce','Force wide layout on WooCommerce pages' => 'כפיית פריסה רחבה בדפי WooCommerce','This ensures the content section is not too narrow on WooCommerce pages including checkout, cart, order received, order pay and account pages.' => 'זה מבטיח שמדור התוכן לא יהיה צר מדי בדפי WooCommerce, כולל דפי תשלום, עגלת קניות, הזמנה שהתקבלה, תשלום עבור הזמנה ודפי חשבון.','WooCommerce Smart Coupons' => 'קופונים חכמים של WooCommerce','Position on checkout page' => 'מיקום בדף התשלום','Choose where to display the available coupons section on the checkout page.' => 'בחר היכן להציג את מדור הקופונים הזמינים בדף התשלום.','Before the progress bar' => 'לפני סרגל ההתקדמות','After the progress bar' => 'לאחר סרגל ההתקדמות','Before coupon codes section' => 'לפני מדור קודי קופון','Format phone numbers according to the rules for each country.' => 'עצבו מספרי טלפון בהתאם לכללים של כל מדינה.','Use precise phone number validation' => 'השתמש באימות מספר טלפון מדויק','This is an experimental feature and may not work as expected in all setups. Use it with caution.' => 'זוהי תכונה ניסיונית וייתכן שלא תפעל כצפוי בכל ההגדרות. יש להשתמש בה בזהירות.','Phone number validation types used when precise validation is enabled.' => 'סוגי אימות מספרי טלפון המשמשים כאשר אימות מדויק מופעל.','Mobile' => 'נייד','Fixed line' => 'קו נייח','Toll free' => 'חינם','Or' => 'אוֹ','Contact' => 'מַגָע','Multi step' => 'רב שלבים','2 columns' => '2 עמודות','1 column' => 'עמודה אחת','Before checkout steps' => 'שלבי הקופה לפני הרכישה','When using the <em>"1 column"</em> checkout layout this option is always set to <em>"Before checkout steps"</em> and also applies to desktop view.' => 'בעת שימוש בפריסת התשלום של <em>&quot;עמודה אחת&quot;,</em> אפשרות זו תמיד מוגדרת ל&quot;שלבי <em>התשלום לפני&quot;</em> וחלה גם על תצוגת שולחן העבודה.','Position for the extra order summary section on mobile.' => 'מיקום עבור מדור סיכום ההזמנות הנוסף בנייד.','The option <em>"On the site header"</em> only applies when using the distraction-free header.' => 'האפשרות <em>&quot;בכותרת האתר&quot;</em> חלה רק בעת שימוש בכותרת ללא הסחות דעת.','On the site header (requires distraction-free header)' => 'כותרת באתר (דורשת כותרת ללא הסחות דעת)','Initial state for the expansible order summary section on mobile.' => 'מצב התחלתי עבור מקטע סיכום ההזמנות הניתן להרחבה בנייד.','We recommend setting it as <em>expanded</em> for the following countries due to regulatory requirements: <strong>Germany</strong>, <strong>Austria</strong>, <strong>Switzerland</strong>, <strong>Netherlands</strong>, <strong>Poland</strong>, <strong>Belgium</strong> and <strong>France</strong>.' => 'אנו ממליצים להגדיר אותו <em>כמורחב</em> עבור המדינות הבאות עקב דרישות רגולטוריות: <strong>גרמניה</strong> , <strong>אוסטריה</strong> , <strong>שוויץ</strong> , <strong>הולנד</strong> , <strong>פולין</strong> , <strong>בלגיה</strong> <strong>וצרפת</strong> .','Collapsed' => 'מכווץ','Expanded' => 'מוּרחָב','Do not show' => 'אל תציג','yes' => 'כֵּן','The shipping phone field may be forced as "required" if the billing address section is displayed after the shipping address section, and the billing phone field is set as "required". This is needed to ensure the shipping address can be copied to the billing address when that option is checked, otherwise the customer might not be able to complete the checkout form.' => 'ייתכן ששדה טלפון המשלוח מוגדר כ&quot;חובה&quot; אם מקטע כתובת החיוב מוצג לאחר מקטע כתובת המשלוח, ושדה טלפון החיוב מוגדר כ&quot;חובה&quot;. זה נחוץ כדי להבטיח שניתן יהיה להעתיק את כתובת המשלוח לכתובת החיוב כאשר אפשרות זו מסומנת, אחרת ייתכן שהלקוח לא יוכל להשלים את טופס התשלום.','The billing phone field may be forced as "required" if the billing address section is displayed before the shipping address section, and the shipping phone field is set as "required". This is needed to ensure the shipping address can be copied to the billing address when that option is checked, otherwise the customer might not be able to complete the checkout form.' => 'ייתכן ששדה טלפון החיוב מוגדר כ&quot;חובה&quot; אם מקטע כתובת החיוב מוצג לפני מקטע כתובת המשלוח, ושדה טלפון המשלוח מוגדר כ&quot;חובה&quot;. זה נחוץ כדי להבטיח שניתן יהיה להעתיק את כתובת המשלוח לכתובת החיוב כאשר אפשרות זו מסומנת, אחרת ייתכן שהלקוח לא יוכל להשלים את טופס התשלום.','Settings profiles' => 'פרופילי הגדרות','Settings profile' => 'פרופיל הגדרות','You do not have permission to perform this action.' => 'אין לך הרשאה לבצע פעולה זו.','You do not have permission to activate plugins.' => 'אין לך הרשאה להפעיל תוספים.','Missing plugin.' => 'תוסף חסר.','Plugin activated.' => 'התוסף הופעל.','The following changes will be applied:' => 'השינויים הבאים יחולו:','Since Fluid Checkout 5.0, settings are saved differently. Legacy options are still stored in the database to allow downgrades to previous versions if needed.' => 'מאז Fluid Checkout 5.0, ההגדרות נשמרות בצורה שונה. אפשרויות מדור קודם עדיין נשמרות במסד הנתונים כדי לאפשר שדרוג לאחור לגרסאות קודמות במידת הצורך.','Your store has been running for about 2 weeks on the new settings so you could clean up legacy options stored in the database. Please note that after cleanup, if you need to downgrade to previous versions of the plugin it will use default values for all settings.' => 'החנות שלך פועלת כבר כשבועיים עם ההגדרות החדשות, כך שתוכל לנקות אפשרויות מדור קודם המאוחסנות במסד הנתונים. שימו לב שלאחר הניקוי, אם תצטרכו לשדרג לאחור לגרסאות קודמות של התוסף, הוא ישתמש בערכי ברירת מחדל עבור כל ההגדרות.','Fluid Checkout settings cleanup' => 'ניקוי הגדרות של Fluid Checkout','Delete leftover options' => 'מחיקת אפשרויות שנותרו','Help us improve Fluid Checkout' => 'עזרו לנו לשפר את Fluid Checkout','Share anonymous site environment reports with Fluid Checkout to get faster support and help us improve compatibility and measure impact. No customer, user, or sensitive data are included. You can choose what is shared anytime from the Tools settings.' => 'שתף דוחות אנונימיים של סביבת אתר עם Fluid Checkout כדי לקבל תמיכה מהירה יותר ולעזור לנו לשפר את התאימות ולמדוד את ההשפעה. לא נכללים נתונים של לקוחות, משתמשים או נתונים רגישים. ניתן לבחור מה משותף בכל עת מהגדרות הכלים.','Enable site environment reports' => 'הפעלת דוחות סביבת אתר','Review settings' => 'סקירת הגדרות','This preview has expired. Reload the admin page to start a new preview.' => 'פג תוקף התצוגה המקדימה הזו. טען מחדש את דף הניהול כדי להתחיל תצוגה מקדימה חדשה.','Preview expired' => 'פג תוקף התצוגה המקדימה','Orders cannot be placed in the preview.' => 'לא ניתן לבצע הזמנות בתצוגה המקדימה.','Logging in is not available in the preview.' => 'כניסה אינה זמינה בתצוגה המקדימה.','Accounts cannot be created in the preview.' => 'לא ניתן ליצור חשבונות בתצוגה המקדימה.','Requests to other sites are blocked in the preview.' => 'בקשות לאתרים אחרים חסומות בתצוגה המקדימה.','Processing…' => 'עיבוד...','Something went wrong. Please try again.' => 'משהו השתבש. אנא נסה שוב.','Activate plugin' => 'הפעלת התוסף','Fluid Checkout PRO - The complete checkout package' => 'Fluid Checkout PRO - חבילת התשלום המלאה','All PRO features + all add-ons, one price. Design templates, optimized cart and order received pages, account matching, and much more.' => 'כל תכונות ה-PRO + כל התוספות, מחיר אחד. תבניות עיצוב, דפי עגלה ודפי הזמנות שהתקבלו אופטימליים, התאמת חשבונות ועוד.','Optimized order pay page' => 'דף תשלום הזמנה אופטימלי','Express checkout buttons from supported payment methods' => 'כפתורי תשלום מהיר מאמצעי תשלום נתמכים','Delayed account creation' => 'יצירת חשבון מושהית','Address autocomplete with Google Maps APIs' => 'השלמה אוטומטית של כתובות עם ממשקי API של מפות גוגל','Multiple saved addresses with the address book' => 'מספר כתובות שנשמרו עם פנקס הכתובות','EU-VAT assistant' => 'עוזר מע&quot;מ באיחוד האירופי','Hide this section' => 'הסתר את הקטע הזה','Learn more' => 'למידע נוסף','Get early access' => 'קבל גישה מוקדמת','Activate add-on' => 'הפעל את התוסף','Get more out of your checkout journey' => 'הפיקו יותר ממסע התשלום שלכם','Test API key' => 'מפתח API לבדיקה','Guided setup' => 'התקנה מודרכת','Options' => 'אפשרויות','Set up layout and design on the <a href="%s">checkout options</a>.' => 'הגדר פריסה ועיצוב <a href="%s">באפשרויות התשלום</a> .','Enable guest checkout and/or review <a href="%s">customer accounts settings</a>.' => 'הפעלת תשלום כאורח ו/או סקירת <a href="%s">הגדרות חשבונות לקוחות</a> .','Enable optimized <a href="%1$s">cart</a>, <a href="%2$s">thank you</a> and <a href="%3$s">order pay</a> pages.' => 'הפעל <a href="%1$s">דפי עגלה</a> , <a href="%2$s">תודה</a> ותשלום <a href="%3$s">להזמנה</a> ממוטבים.','Enable <a href="%s">address autocomplete</a> from Google Maps.' => 'הפעל <a href="%s">השלמה אוטומטית</a> של כתובות ממפות גוגל.','Enable multiple saved addresses with <a href="%s">address book</a>.' => 'הפעל כתובות שמורות מרובות באמצעות <a href="%s">פנקס כתובות</a> .','Check if there are any <a href="%s">integration options</a> available for the theme or other plugins you have installed.' => 'בדוק אם יש <a href="%s">אפשרויות אינטגרציה</a> זמינות עבור התבנית או עבור תוספים אחרים שהתקנת.','Get faster support and help us improve compatibility and measure impact. <a href="%s">Enable usage tracking</a> from the tools settings.' => 'קבל תמיכה מהירה יותר ועזור לנו לשפר תאימות ולמדוד השפעה. <a href="%s">הפעל מעקב אחר שימוש</a> מהגדרות הכלים.','Missing settings tab.' => 'חסרה לשונית הגדרות.','Getting started' => 'תחילת העבודה','<strong>Great! Your checkout page is now running on Fluid Checkout.</strong> Here are a few steps to get started:' => '<strong>מעולה! דף התשלום שלך פועל כעת ב-Fluid Checkout.</strong> הנה כמה צעדים כדי להתחיל:','Completed' => 'הושלם','Preview report data' => 'תצוגה מקדימה של נתוני הדוח','Send now' => 'שלח עכשיו','Auto-detect' => 'זיהוי אוטומטי','Afrikaans' => 'אפריקאנס','Albanian' => 'אלבני','Amharic' => 'אמהרית','Arabic' => 'עֲרָבִית','Armenian' => 'אַרְמֶנִי','Azerbaijani' => 'אזרבייג&#39;נית','Basque' => 'באסקית','Belarusian' => 'בלארוסית','Bengali' => 'בנגלית','Bosnian' => 'בוסנית','Bulgarian' => 'בולגרית','Burmese' => 'בורמזי','Catalan' => 'קטלאנית','Chinese' => 'סִינִית','Chinese (Simplified)' => 'סינית (פשוטה)','Chinese (Hong Kong)' => 'סינית (הונג קונג)','Chinese (Traditional)' => 'סינית (מסורתית)','Croatian' => 'קרואטית','Czech' => 'צ&#39;כית','Danish' => 'דַנִי','Dutch' => 'הוֹלַנדִי','English' => 'אַנגְלִית','English (Australian)' => 'אנגלית (אוסטרלית)','English (Great Britain)' => 'אנגלית (בריטניה הגדולה)','Estonian' => 'אסטונית','Farsi' => 'פרסית','Finnish' => 'פִינִית','Filipino' => 'פיליפינית','French' => 'צָרְפָתִית','French (Canadian)' => 'צרפתית (קנדית)','Galician' => 'גליציאנית','Georgian' => 'גרוזיני','German' => 'גֶרמָנִיָת','Greek' => 'יוונית','Gujarati' => 'גוג&#39;ראטי','Hebrew' => 'עִברִית','Hindi' => 'הינדי','Hungarian' => 'הוּנגָרִי','Icelandic' => 'איסלנדית','Indonesian' => 'אינדונזית','Italian' => 'אִיטַלְקִית','Japanese' => 'יַפָּנִית','Kannada' => 'קאנדה','Kazakh' => 'קזחית','Khmer' => 'חמר','Korean' => 'קוריאנית','Kyrgyz' => 'קירגיזית','Lao' => 'לאו','Latvian' => 'לטבית','Lithuanian' => 'ליטאי','Macedonian' => 'מקדונית','Malay' => 'מלאית','Malayalam' => 'מלאיאלאם','Marathi' => 'מרטהי','Mongolian' => 'מוֹנגוֹלִי','Nepali' => 'נפאלית','Norwegian' => 'נורווגית','Polish' => 'פּוֹלָנִית','Portuguese' => 'פורטוגזית','Portuguese (Brazil)' => 'פורטוגזית (ברזיל)','Portuguese (Portugal)' => 'פורטוגזית (פורטוגל)','Punjabi' => 'פנג&#39;אבי','Romanian' => 'רומנית','Russian' => 'רוּסִי','Serbian' => 'סרבית','Sinhalese' => 'סינהלית','Slovak' => 'סלובקית','Slovenian' => 'סלובנית','Spanish' => 'סְפָרַדִית','Spanish (Latin America)' => 'ספרדית (אמריקה הלטינית)','Swahili' => 'סוואהילית','Swedish' => 'שוודית','Tamil' => 'טמילית','Telugu' => 'טלוגו','Thai' => 'תאילנדי','Turkish' => 'טוּרקִית','Ukrainian' => 'אוקראינית','Urdu' => 'אורדו','Vietnamese' => 'וייטנאמית','Zulu' => 'זולו','Google address autocomplete' => 'השלמה אוטומטית של כתובות גוגל','Google Places API version' => 'גרסת ה-API של גוגל מקומות','Choose which version of the Google Places API to use. We recommend moving to the new Places API as soon as possible.' => 'בחר באיזו גרסה של ממשק ה-API של מקומות גוגל להשתמש. אנו ממליצים לעבור לממשק ה-API החדש של מקומות בהקדם האפשרי.','We recommend using "Places API (New)" as effective March 1, 2025, Google will move the "Places API (Legacy)" version into Legacy status, meaning you will no longer be able to enable this service for new API keys and that that version of the API will eventually not be available anymore. Existing accounts already using the Legacy API may continue to work without disruptions.' => 'אנו ממליצים להשתמש ב-&quot;Places API (חדש)&quot; מכיוון שהחל מ-1 במרץ 2025, גוגל תעביר את גרסת &quot;Places API (Legacy)&quot; לסטטוס Legacy, כלומר לא תוכלו עוד להפעיל שירות זה עבור מפתחות API חדשים וגרסה זו של ה-API לא תהיה זמינה יותר בסופו של דבר. חשבונות קיימים שכבר משתמשים ב-Legacy API עשויים להמשיך לפעול ללא הפרעות.','(Recommended)' => '(מוּמלָץ)','Google API key' => 'מפתח ה-API של גוגל','Paste your Google API key and use the test button to confirm it works for this website. Make sure the key is valid and allowed for your domain, otherwise the address field might get blocked preventing customers from completing their orders.' => 'הדבק את מפתח ה-API של גוגל שלך והשתמש בלחצן הבדיקה כדי לאשר שהוא פועל עבור אתר זה. ודא שהמפתח תקף ומותר עבור הדומיין שלך, אחרת שדה הכתובת עלול להיחסם ולמנוע מלקוחות להשלים את הזמנותיהם.','Enable Google address autocomplete' => 'הפעל השלמה אוטומטית של כתובות בגוגל','Enable address autocompletion using the Google Maps APIs.' => 'הפעל השלמה אוטומטית של כתובות באמצעות ממשקי ה-API של מפות גוגל.','Google API language' => 'שפת ה-API של גוגל','This language will be used to display the Google Places API address suggestions and addresses will also be autocompleted in this language.' => 'שפה זו תשמש להצגת הצעות לכתובות של ממשק ה-API של מקומות גוגל, וגם כתובות יושלמו אוטומטית בשפה זו.','Result types' => 'סוגי תוצאות','Leave empty to accept any type of results, which usually yields better matching results. <a href="%s" target="_blank">See documentation for more details</a>. <br>Select up to 5 types of address search results to return on address autocomplete fields. <br>Visit the Google Maps documentation to learn more about the <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">supported types</a>.' => 'השאר ריק כדי לקבל כל סוג של תוצאות, שבדרך כלל מניבות תוצאות תואמות טובות יותר. <a href="%s" target="_blank">עיין בתיעוד לקבלת פרטים נוספים</a> .<br> בחר עד 5 סוגים של תוצאות חיפוש כתובות כדי להחזיר בשדות השלמה אוטומטית של כתובות.<br> בקר בתיעוד של מפות גוגל כדי ללמוד עוד על <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">הסוגים הנתמכים</a> .','Result types (Legacy API)' => 'סוגי תוצאות (API מדור קודם)','Which type of address search results to return when using Places API (Legacy). <br>Visit the documentation of the Legacy Google Places API to learn more about the <a href="https://developers.google.com/maps/documentation/places/web-service/supported_types#table3" target="_blank">supported types</a>.' => 'איזה סוג של תוצאות חיפוש כתובות להחזיר בעת שימוש ב-Places API (Legacy).<br> בקר בתיעוד של ממשק ה-API של מקומות גוגל (Legacy Google Places API) כדי ללמוד עוד על <a href="https://developers.google.com/maps/documentation/places/web-service/supported_types#table3" target="_blank">הסוגים הנתמכים</a> .','Company fields' => 'שדות החברה','Enable autocomplete for the company name if available' => 'הפעל השלמה אוטומטית עבור שם החברה אם זמין','Enable autocompletion of the company field with the company name information when returned from the Google Maps APIs.' => 'הפעל השלמה אוטומטית של שדה החברה עם פרטי שם החברה כאשר הוא מוחזר מממשקי ה-API של מפות גוגל.','Business search' => 'חיפוש עסקי','Enable search for businesses in the company field' => 'אפשר חיפוש עסקים בתחום החברה','Enable suggestion of addresses associated with a business when typing in the company field, then autocomplete all addresses fields when a business is selected from the suggestions.' => 'הפעל הצעה לכתובות המשויכות לעסק בעת הקלדה בשדה החברה, ולאחר מכן השלם אוטומטית את כל שדות הכתובות כאשר עסק נבחר מההצעות.','Company result types' => 'סוגי תוצאות החברה','Select up to 5 types of address search results to return on autocomplete company fields. <br>Recommended value is <code>establishment</code>, which includes most types of businesses. <br>Leave empty to accept any type of results, including results that are not related to businesses. <br>Visit the Google Maps documentation to learn more about the <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">supported types</a>.' => 'בחר עד 5 סוגי תוצאות חיפוש כתובות שיוחזרו בשדות חברה להשלמה אוטומטית.<br> הערך המומלץ הוא <code>establishment</code> , הכולל את רוב סוגי העסקים.<br> השאר ריק כדי לקבל כל סוג של תוצאות, כולל תוצאות שאינן קשורות לעסקים.<br> בקר בתיעוד של מפות גוגל כדי ללמוד עוד על <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">הסוגים הנתמכים</a> .','Google logo' => 'לוגו גוגל','Show text and logo "Powered by Google"' => 'הצג טקסט ולוגו &quot;מופעל על ידי גוגל&quot;','When checked, the text and logo "Powered by Google" will be displayed at the bottom of the address autocomplete suggestions box.' => 'כאשר האפשרות מסומנת, הטקסט והלוגו &quot;מופעל על ידי גוגל&quot; יוצגו בתחתית תיבת ההצעות להשלמת כתובות אוטומטית.','Brasil API address autocomplete' => 'השלמה אוטומטית של כתובת API של ברזיל','Brasil API' => 'API של ברזיל','Enable Brasil API address autocomplete for CEP fields' => 'הפעל השלמה אוטומטית של כתובות API של Brasil עבור שדות CEP','Use Brasil API to retrieve and autofill addresses using the CEP/Postcode field. Only relevant for Brazilian addresses.' => 'השתמש ב-Brasil API כדי לאחזר ולמלא אוטומטית כתובות באמצעות שדה CEP/מיקוד. רלוונטי רק לכתובות ברזילאיות.','API version' => 'גרסת API','Choose which version of the Brasil API CEP method to use.' => 'בחר באיזו גרסה של שיטת CEP של API ברזיל להשתמש.','Address book migration' => 'העברת פנקס כתובות','WooCommerce addresses' => 'כתובות WooCommerce','Copy existing shipping and billing addresses from WooCommerce into the customers\' address book.' => 'העתק כתובות משלוח וכתובות חיוב קיימות מ-WooCommerce לפנקס הכתובות של הלקוחות.','Enable the address book feature' => 'הפעל את תכונת פנקס הכתובות','Allow customers to save multiple addresses and define the default address to be used for shipping and billing.' => 'לאפשר ללקוחות לשמור מספר כתובות ולהגדיר את כתובת ברירת המחדל שתשמש למשלוח ולחיוב.','Address labels' => 'תוויות כתובת','Allow customers to add a custom label for each address' => 'לאפשר ללקוחות להוסיף תווית מותאמת אישית לכל כתובת','Address labels make it easier to for customers to distinguish between their saved addresses (ie.: "Mom\'s House"). The address labels are private to the customers, and will not be displayed or printed on the order details page or invoices.' => 'תוויות כתובת מקלות על הלקוחות להבחין בין הכתובות השמורות שלהם (לדוגמה: &quot;בית אמא&quot;). תוויות הכתובת הן פרטיות עבור הלקוחות, ולא יוצגו או יודפסו בדף פרטי ההזמנה או בחשבוניות.','Display layout' => 'פריסת תצוגה','Choose how saved addresses are displayed at checkout and on the cart.' => 'בחר כיצד יוצגו כתובות שנשמרו בקופה ובעגלת הקניות.','Applies at checkout and on the cart. Saved addresses on the account page always use the cards layout.' => 'חל בקופה ובעגלת הקניות. כתובות שנשמרו בדף החשבון תמיד משתמשות בפריסה של כרטיסים.','Address cards' => 'כרטיסי כתובת','Address list' => 'רשימת כתובות','Dropdown field' => 'שדה נפתח','Address search' => 'חיפוש כתובת','Show address search filter on frontend when customer has at least this number of saved addresses available.' => 'הצג מסנן חיפוש כתובות בממשק המשתמש כאשר ללקוח יש לפחות מספר זה של כתובות שמורות זמינות.','Not used when display layout is set to dropdown field.' => 'לא בשימוש כאשר פריסת התצוגה מוגדרת לשדה נפתח.','Addresses' => 'כתובות','Enable cart page optimizations to see more options' => 'הפעל אופטימיזציות של דפי עגלת קניות כדי לראות אפשרויות נוספות','Sticky order summary' => 'סיכום הזמנה דביקה','Select position where to display the coupon codes section on the cart page. Only applicable when AJAX cart is enabled, and if use of coupon codes are enabled in the WooCommerce settings.' => 'בחר את המיקום שבו יוצג מדור קודי הקופון בדף עגלת הקניות. רלוונטי רק כאשר עגלת AJAX מופעלת, ואם השימוש בקודי קופון מופעל בהגדרות WooCommerce.','Layout of cross-sell' => 'פריסת מכירה צולבת','Cross-sells displayed' => 'מכירות צולבות מוצגות','Items' => 'פריטים','Cart page optimization' => 'אופטימיזציה של דף עגלת קניות','Give your cart the same clear, conversion-focused layout as your checkout.' => 'תן לעגלת הקניות שלך את אותה פריסה ברורה וממוקדת המרות כמו בקופה.','Match the cart layout to the checkout page for a consistent purchase journey.' => 'התאם את פריסת עגלת הקניות לדף התשלום לקבלת מסע קנייה עקבי.','Keep the cart always updated in the background, no full page reloads when quantities change.' => 'שמור על עגלת הקניות מעודכנת ברקע, אין טעינה מחדש של עמוד שלם כאשר הכמויות משתנות.','Place coupon codes, shipping, and cross-sells exactly where they convert best.' => 'מקמו קודי קופון, משלוחים ומכירות צולבות בדיוק במקומות שבהם הם מניבים הכי הרבה המרות.','Keep the order summary visible while scrolling, and add trust symbols where shoppers need reassurance.' => 'שמרו על סיכום ההזמנה גלוי בזמן הגלילה, והוסיפו סמלי אמון במקומות בהם קונים זקוקים לביטחון.','Columns' => 'עמודות','General styles for the checkout steps, order summary and other sections. Applies to other checkout, cart, thank you (order received), and view order pages.' => 'סגנונות כלליים לשלבי התשלום, סיכום ההזמנה וסעיפים אחרים. חל על דפי התשלום האחרים, עגלת הקניות, תודה (הזמנה שהתקבלה) ותצוגת הזמנה.','When using the <em>"1 column"</em> layout with the <em>"Split"</em> design template, a right column is shown only if the page sidebar widget area is active (Checkout Sidebar, Cart Sidebar, or Order Received Sidebar). Otherwise the page stays as a single column with Split styles.' => 'בעת שימוש בפריסה של <em>&quot;עמודה אחת&quot;</em> עם תבנית העיצוב <em>&quot;פיצול&quot;</em> , עמודה ימנית מוצגת רק אם אזור הווידג&#39;ט של סרגל הצד של הדף פעיל (סרגל צד של תשלום, סרגל צד של עגלת קניות או סרגל צד של הזמנות שהתקבלה). אחרת, הדף נשאר כעמודה אחת עם סגנונות פיצול.','Split column background' => 'רקע עמודה מפוצלת','Choose a background color for the Split design secondary column. Leave empty to use the order summary background color.' => 'בחר צבע רקע עבור העמודה המשנית של עיצוב מפוצל. השאר ריק כדי להשתמש בצבע הרקע של סיכום ההזמנה.','Page templates' => 'תבניות דפים','Checkout template' => 'תבנית תשלום','Recommended for fewer distractions at checkout. <a href="https://baymard.com/blog/cart-abandonment" target="_blank">Read the research about cart abandonment</a>.' => 'מומלץ להפחתת הסחות דעת בקופה. <a href="https://baymard.com/blog/cart-abandonment" target="_blank">קרא את המחקר על נטישת עגלת קניות</a> .','Sticky progress bar' => 'סרגל התקדמות דביק','Progress bar style' => 'סגנון סרגל התקדמות','Order totals' => 'סך כל ההזמנות','Background color' => 'צבע רקע','Action link' => 'קישור פעולה','Mobile order summary' => 'סיכום הזמנות בנייד','Mobile initial state' => 'מצב התחלתי של נייד','Enable editing cart items at checkout' => 'הפעל עריכת פריטי עגלה בקופה','Allow customers to change product quantities or remove items directly at the checkout page.' => 'לאפשר ללקוחות לשנות כמויות מוצרים או להסיר פריטים ישירות בדף התשלום.','Cart item errors' => 'שגיאות בפריטים בעגלה','Only applicable when coupon code is displayed as a separate section on the checkout or cart pages, and if use of coupon codes are enabled in the WooCommerce settings.' => 'רלוונטי רק כאשר קוד הקופון מוצג כקטע נפרד בדפי התשלום או עגלת הקניות, ואם השימוש בקודי קופון מופעל בהגדרות WooCommerce.','Coupon codes position' => 'מיקום קודי קופון','Apply coupon button' => 'כפתור החלת קופון','Select style of the "apply coupon" button.' => 'בחר סגנון של כפתור &quot;החל קופון&quot;.','Address line 2' => 'שורת כתובת 2','This setting is shared between the Checkout and Local pickup sections. On the Local pickup section, it also decides whether the Ship/Pickup selector shows inside the shipping method section (before the address) or as a separate section (after).' => 'הגדרה זו משותפת למקטעי &quot;קופה&quot; ו&quot;איסוף מקומי&quot;. במקטע &quot;איסוף מקומי&quot;, היא גם קובעת האם בורר המשלוח/איסוף יופיע בתוך מקטע שיטת המשלוח (לפני הכתובת) או כמקטע נפרד (אחרי).','Customer accounts' => 'חשבונות לקוחות','Guest checkout' => 'צ&#39;ק-אאוט של האורחים','Guest checkout, login, and account creation options from the WooCommerce Accounts settings page. They are managed here for your convenience, and so you can use different values per settings profile.' => 'אפשרויות תשלום, כניסה ויצירת חשבון כאורח מדף ההגדרות של חשבונות WooCommerce. הן מנוהלות כאן לנוחיותך, ולכן תוכל להשתמש בערכים שונים לכל פרופיל הגדרות.','Allow customers to checkout without an account' => 'לאפשר ללקוחות לבצע תשלום ללא חשבון','<strong>Recommended</strong> so customers are not asked to create an account or log in during checkout, which can lower conversion rates.' => '<strong>מומלץ</strong> כך שלקוחות לא יתבקשו ליצור חשבון או להתחבר במהלך התשלום, מה שיכול להוריד את שיעורי ההמרה.','When disabled, customers must log in or create an account to complete the purchase.' => 'כאשר האפשרות מושבתת, על הלקוחות להתחבר או ליצור חשבון כדי להשלים את הרכישה.','Login at checkout' => 'התחברות בקופה','Enable log-in during checkout' => 'הפעלת כניסה במהלך התשלום','Show a link for returning customers to log in from the checkout page.' => 'הצג קישור ללקוחות חוזרים להתחברות מדף התשלום.','Account creation' => 'יצירת חשבון','Allow customers to create an account during checkout' => 'לאפשר ללקוחות ליצור חשבון במהלך התשלום','Customers can create an account before placing their order.' => 'לקוחות יכולים ליצור חשבון לפני ביצוע ההזמנה.','Allow customers to create an account from the My account page' => 'לאפשר ללקוחות ליצור חשבון מדף &quot;החשבון שלי&quot;','Customers can register a new account from the My account page.' => 'לקוחות יכולים לפתוח חשבון חדש מדף &quot;החשבון שלי&quot;.','Username' => 'שם משתמש','Generate from customer\'s name' => 'יצירה משם הלקוח','<strong>Recommended</strong> so customers are not asked to choose a username during checkout, which can lower conversion rates.' => '<strong>מומלץ</strong> כדי שלא יתבקשו לקוחות לבחור שם משתמש במהלך התשלום, דבר שיכול להוריד את שיעורי ההמרה.','A username is generated from the customer name, or from the email address when a name cannot be used.' => 'שם משתמש נוצר משם הלקוח, או מכתובת הדוא&quot;ל כאשר לא ניתן להשתמש בשם.','Password' => 'סִיסמָה','Send password setup link' => 'שלח קישור להגדרת סיסמה','<strong>Recommended</strong> so customers are not asked to set a password during checkout, which can lower conversion rates.' => '<strong>מומלץ</strong> כדי שלא יתבקשו לקוחות להגדיר סיסמה במהלך התשלום, דבר שיכול להוריד את שיעורי ההמרה.','Customers receive an email to create their password securely.' => 'לקוחות מקבלים אימייל ליצירת סיסמה בצורה מאובטחת.','Let registered customers complete checkout without logging in and associate the order with their existing account when contact details match.' => 'לאפשר ללקוחות רשומים להשלים את התשלום מבלי להתחבר ולקשר את ההזמנה לחשבון הקיים שלהם כאשר פרטי הקשר תואמים.','Existing account message' => 'הודעת חשבון קיים','Let customers create an account after placing their order, from the thank you page.' => 'אפשרו ללקוחות ליצור חשבון לאחר ביצוע ההזמנה שלהם, מדף התודה.','Options in this section are available when guest checkout and account matching are enabled. Enable both features above to configure delayed account creation.' => 'האפשרויות בסעיף זה זמינות כאשר ביצוע הזמנה כאורח והתאמת חשבונות מופעלים. הפעל את שתי התכונות שלמעלה כדי להגדיר יצירת חשבון מושהית.','Enable delayed account creation' => 'הפעל יצירת חשבון מושהית','Enable delayed account creation when both guest checkout and account matching are enabled.' => 'הפעל יצירת חשבון בהשהיה כאשר גם תשלום כאורח וגם התאמת חשבון מופעלים.','Section position' => 'מיקום המקטע','Before customer details section' => 'לפני סעיף פרטי הלקוח','After customer details section' => 'אחרי מדור פרטי הלקוח','Account creation benefits' => 'יתרונות יצירת חשבון','Leaving the field empty will display the default text.' => 'השארת השדה ריק תציג את טקסט ברירת המחדל.','Inline buttons' => 'כפתורים מוטבעים','Required fields' => 'שדות חובה','Enable gift message fields at checkout' => 'הפעל שדות הודעה למתנה בקופה','Expanded gift message' => 'הודעת מתנה מורחבת','Display gift message field always expanded' => 'שדה הודעת המתנה תמיד מורחב','Gift message in order details' => 'הודעת מתנה בפרטי ההזמנה','No integrations available at the moment on this section. The options related to each plugin and theme will only appear here when that plugin or theme is activated.' => 'אין אינטגרציות זמינות כרגע במקטע זה. האפשרויות הקשורות לכל תוסף ותבנית יופיעו כאן רק כאשר התוסף או התבנית מופעלים.','Phone fields' => 'שדות טלפון','Field visibility' => 'נראות השדה','Field position' => 'מיקום בשטח','Phone country code & validation' => 'קידומת בינלאומית של הטלפון ואימות','Country' => 'מְדִינָה','Enable country on phone fields' => 'הפעל מדינה בשדות טלפון','Filter countries for shipping or billing' => 'סנן מדינות למשלוח או לחיוב','Limit the country selector on each phone field to the countries allowed for shipping or billing on your store.' => 'הגבל את בורר המדינות בכל שדה טלפון למדינות המותרות למשלוח או לחיוב בחנות שלך.','Validation' => 'מַתַן תוֹקֵף','Enable simple validation based on country rules' => 'הפעלת אימות פשוט המבוסס על כללי מדינה','Checks that the phone number is valid for the selected country, including country code and length.' => 'בודק שמספר הטלפון תקף עבור המדינה שנבחרה, כולל קידומת המדינה והאורך.','Stricter check that the number is a valid mobile, fixed line, or other accepted type for the selected country. May reject some valid numbers.' => 'בדיקה קפדנית יותר שהמספר הוא מספר נייד, קווי או סוג אחר המקובל במדינה שנבחרה. ייתכן שידחה מספרים תקינים מסוימים.','Validation types' => 'סוגי אימות','Placeholders' => 'מצייני מיקום','No license keys to manage at the moment. License keys will appear here when a licensed Fluid Checkout plugin or add-on is active.' => 'אין מפתחות רישיון לניהול כרגע. מפתחות רישיון יופיעו כאן כאשר תוסף או תוסף מורשה של Fluid Checkout פעילים.','Default delivery type' => 'סוג משלוח ברירת מחדל','Choose which delivery type will be selected by default.' => 'בחר איזה סוג משלוח ייבחר כברירת מחדל.','Shipping zone fields' => 'שדות אזור משלוח','Choose which fields will be displayed for the local pickup shipping zone filter fields. Leave empty to show all available options.' => 'בחר אילו שדות יוצגו עבור שדות הסינון של אזור המשלוח של איסוף מקומי. השאר ריק כדי להציג את כל האפשרויות הזמינות.','These fields will be displayed as a filter for the local pickup shipping methods. Some fields might still appear at checkout when not selected here, if compatible plugins require them to work properly.' => 'שדות אלה יוצגו כמסנן עבור שיטות משלוח לאיסוף מקומי. ייתכן שחלק מהשדות עדיין יופיעו בקופה אם לא נבחרו כאן, אם תוספים תואמים דורשים מהם לפעול כראוי.','Order shipping address' => 'כתובת למשלוח ההזמנה','Order pay page optimization' => 'אופטימיזציה של דף תשלום הזמנות','Give unpaid orders the same clear, conversion-focused layout as checkout.' => 'תנו להזמנות שלא שולמו את אותה פריסה ברורה וממוקדת המרות כמו בקופה.','Optimize the layout of the order pay page for orders pending payment.' => 'בצע אופטימיזציה של הפריסה של דף התשלום עבור הזמנות הממתינות לתשלום.','Match the order pay experience to your checkout for a consistent purchase journey.' => 'התאם את חוויית התשלום בהזמנה לקופה שלך לקבלת מסע קנייה עקבי.','Add trust symbols and badges where shoppers need reassurance before paying.' => 'הוסיפו סמלי אמון ותגים היכן שקונים זקוקים לביטחון לפני התשלום.','Thank you page optimization' => 'תודה על אופטימיזציית העמוד','Make the thank you page and order details clearer for customers after they buy.' => 'הפכו את דף התודה ופרטי ההזמנה לברורים יותר עבור הלקוחות לאחר הרכישה.','Optimize the thank you page and account order details with a clearer layout.' => 'בצע אופטימיזציה של דף התודה ופרטי הזמנת החשבון עם פריסה ברורה יותר.','Show order status progress, actions, downloads, and notes where they make sense.' => 'הצג את התקדמות סטטוס ההזמנה, פעולות, הורדות והערות היכן שהם הגיוניים.','Customize order details sections on email notifications.' => 'התאם אישית את מדורי פרטי ההזמנה בהודעות הדוא&quot;ל.','Add trust symbols and badges where shoppers need reassurance after purchase.' => 'הוסיפו סמלי אמון ותגים היכן שקונים זקוקים לביטחון לאחר הרכישה.','Email notifications' => 'התראות דוא&quot;ל','Enable thank you page and order details optimizations to see more options' => 'הפעל אופטימיזציות של דף התודה ופרטי ההזמנה כדי לראות אפשרויות נוספות','Use wide layout on thank you page' => 'השתמש בפריסה רחבה בדף התודה','These options affect the thank you page, view order details on account pages and on email notifications.' => 'אפשרויות אלו משפיעות על דף התודה, על צפייה בפרטי ההזמנה בדפי החשבון ועל התראות הדוא&quot;ל.','Save settings' => 'שמירת הגדרות','Docs' => 'מסמכים','Cart' => 'עֲגָלָה','Thank you' => 'תודה רבה','Address autocomplete' => 'השלמה אוטומטית של כתובת','Trust badges' => 'תגי אמון','You do not have permission to save these settings.' => 'אין לך הרשאה לשמור הגדרות אלה.','Invalid save request.' => 'בקשת שמירה לא חוקית.','Your settings have been saved.' => 'ההגדרות שלך נשמרו.','Saving...' => 'חִסָכוֹן...','Settings could not be saved. Please try again.' => 'לא ניתן היה לשמור את ההגדרות. אנא נסה שוב.','Dismiss notice' => 'דחיית הודעה','Open settings menu' => 'פתח את תפריט ההגדרות','Close settings menu' => 'סגור את תפריט ההגדרות','Preview' => 'תצוגה מקדימה','Expand preview' => 'הרחב את התצוגה המקדימה','Collapse preview' => 'כווץ את התצוגה המקדימה','Show header and footer' => 'הצג כותרת עליונה ותחתונה','Hide header and footer' => 'הסתר כותרת עליונה ותחתונה','Page preview' => 'תצוגה מקדימה של הדף','Preview viewport' => 'תצוגה מקדימה של חלון התצוגה','Tablet' => 'לוּחַ','Desktop' => 'שולחן עבודה','Preview width' => 'רוחב התצוגה המקדימה','Decrease width' => 'הקטנת רוחב','Preview width in pixels' => 'רוחב התצוגה המקדימה בפיקסלים','Increase width' => 'הגדלת רוחב','Preview as' => 'תצוגה מקדימה כ','Guest' => 'אוֹרֵחַ','Logged in' => 'מחובר/ת','Preview page' => 'דף תצוגה מקדימה','Expand preview for a closer look' => 'הרחב את התצוגה המקדימה למבט מקרוב','Available with %s.' => 'זמין עם %s.','Turn them on' => 'הפעילו אותם','Optimizations for this page are turned off. %s to preview the page.' => 'אופטימיזציות עבור דף זה כבויות. %s כדי להציג את הדף בתצוגה מקדימה.','%s preview' => 'תצוגה מקדימה של %s','Isolated session · nothing is saved' => 'סשן מבודד · שום דבר לא נשמר','Usage tracking' => 'מעקב שימוש','Send non-sensitive site environment reports to help Fluid Checkout improve compatibility. Reports are not sent until enabled in the options below.' => 'שלח דוחות על סביבת אתר שאינה רגישה כדי לעזור ל-Fluid Checkout לשפר את התאימות. דוחות לא נשלחים עד להפעלתם באפשרויות שלהלן.','Send usage tracking reports to Fluid Checkout' => 'שלח דוחות מעקב שימוש ל-Fluid Checkout','These reports help us improve compatibility and support for your site and are sent weekly when enabled.' => 'דוחות אלה עוזרים לנו לשפר את התאימות והתמיכה באתר שלך ונשלחים מדי שבוע כאשר הם מופעלים.','No customer, admin user, or any other sensitive data is included in the reports.' => 'הדוחות לא כוללים נתונים של לקוחות, משתמשים של מנהלי מערכת או כל מידע רגיש אחר.','Basic environment info' => 'מידע בסיסי על הסביבה','WordPress, PHP, WooCommerce, theme, and plugin list data. Always included when reporting is enabled. Helps us understand the environment your site is running in.' => 'נתוני רשימת תבניות וורדפרס, PHP, WooCommerce. תמיד כלולים כאשר הדיווח מופעל. עוזרים לנו להבין את הסביבה שבה האתר שלך פועל.','Plugin settings' => 'הגדרות תוסף','Sends Fluid Checkout plugin settings to help with support requests and helps us understand how you are using our plugins.' => 'שולח הגדרות תוסף Fluid Checkout כדי לסייע בבקשות תמיכה ועוזר לנו להבין כיצד אתה משתמש בתוספים שלנו.','Coming soon' => 'בקרוב','Sales metrics' => 'מדדי מכירות','Monthly order count and total sales for one year prior to installing Fluid Checkout up to today. Helps us understand if you are making more money with our plugins installed. No customer or user data is ever sent.' => 'ספירת הזמנות חודשית וסך המכירות במשך שנה לפני התקנת Fluid Checkout ועד היום. עוזר לנו להבין אם אתם מרוויחים יותר כסף עם התוספים שלנו המותקנים. לא נשלחים נתוני לקוחות או משתמשים לעולם.','Utilities' => 'שירותים','Use <code>TomSelect</code> dropdown components instead of <code>select2</code>' => 'השתמש ברכיבי התפריט הנפתח <code>TomSelect</code> במקום ב- <code>select2</code>','TomSelect is a simpler dropdown selection component which is less prone to errors than Select2, while offering the same functionality.' => 'TomSelect הוא רכיב בחירה נפתח פשוט יותר, פחות נוטה לשגיאות מאשר Select2, תוך שהוא מציע את אותה פונקציונליות.','Sets the font size inside form fields to 16px on pages optimized by this plugin to avoid automatically zooming in when interacting with form fields on small devices.' => 'מגדיר את גודל הגופן בתוך שדות טופס ל-16 פיקסלים בדפים שעברו אופטימיזציה על ידי תוסף זה כדי למנוע התקרבות אוטומטית בעת אינטראקציה עם שדות טופס במכשירים קטנים.','Safari and other browsers might automatically zoom in on mobile devices to make the text easier to read when the font size is smaller than 16px.' => 'ייתכן שספארי ודפדפנים אחרים יתקרבו אוטומטית במכשירים ניידים כדי להקל על קריאת הטקסט כאשר גודל הגופן קטן מ-16 פיקסלים.','Enable script processing tracking on the browser console.' => 'הפעל מעקב אחר עיבוד סקריפטים בקונסולת הדפדפן.','Unminified assets' => 'נכסים לא ממוזערים','Google Maps scripts' => 'סקריפטים של מפות גוגל','Do not remove duplicate Google Maps scripts' => 'אל תסיר סקריפטים כפולים של מפות גוגל','When enabled, duplicate Google Maps scripts will NOT be removed which can cause errors and performance issues. Only use this option while troubleshooting.' => 'כאשר האפשרות מופעלת, סקריפטים כפולים של מפות גוגל לא יוסרו, דבר שעלול לגרום לשגיאות ובעיות ביצועים. השתמש באפשרות זו רק בעת פתרון בעיות.','Widget areas' => 'אזורי ווידג&#39;ט','Last step on mobile' => 'שלב אחרון בנייד','Display widgets only at last step on mobile' => 'הצגת ווידג&#39;טים רק בשלב האחרון בנייד','Display checkout trust badge widgets only when viewing the last checkout step on mobile devices' => 'הצג ווידג&#39;טים של תג אמון בקופה רק בעת צפייה בשלב התשלום האחרון במכשירים ניידים','Standard' => 'תֶקֶן','VAT number field' => 'שדה מספר מע&quot;מ','Add a VAT number field to the billing form.' => 'הוסף שדה מספר מע&quot;מ לטופס החיוב.','Field label' => 'תווית שדה','Set the label of the VAT number field (ie. VAT number). On multi-language websites, it is better to leave this field empty and translate the original string.' => 'הגדר את התווית של שדה מספר המע&quot;מ (לדוגמה, מספר מע&quot;מ). באתרים מרובי שפות, עדיף להשאיר שדה זה ריק ולתרגם את המחרוזת המקורית.','VAT Number' => 'מספר מע&quot;מ','EU-VAT' => 'מע&quot;מ באיחוד האירופי','Enable the VAT number field to see more options' => 'הפעל את שדה מספר המע&quot;מ כדי לראות אפשרויות נוספות','VAT validation' => 'אימות מע&quot;מ','Validate VAT number field for EU-VAT during checkout' => 'אימות שדה מספר מע&quot;מ עבור מע&quot;מ באיחוד האירופי במהלך התשלום','Checks if the VAT Number provided is a valid VAT number registered on the European VIES Database (VAT Information Exchange System).' => 'בודק אם מספר המע&quot;מ שסופק הוא מספר מע&quot;מ תקף הרשום במסד הנתונים האירופי VIES (מערכת חילופי מידע על מע&quot;מ).','Shop VAT number' => 'מספר מע&quot;מ בחנות','The shop\'s VAT number used for requesting EU-VAT validation, and printed on invoices. <br><strong>We strongly recommend adding your Shop VAT number</strong> as otherwise the VIES consultation results might not be valid for accounting purposes. <br>Ie.: <code>ATU99999999</code> or <code>EE999999999</code>.' => 'מספר המע&quot;מ של החנות המשמש לבקשת אימות מע&quot;מ של האיחוד האירופי, ומודפס על חשבוניות.<br> <strong>אנו ממליצים בחום להוסיף את מספר המע&quot;מ של החנות שלך</strong> , אחרת תוצאות הייעוץ של VIES עלולות לא להיות תקפות למטרות חשבונאיות.<br> כלומר: <code>ATU99999999</code> או <code>EE999999999</code> .','Reverse charge' => 'חיוב הפוך','Apply reverse charge mechanism' => 'החלת מנגנון חיוב הפוך','Set tax rate to zero and display "Reverse charge" on invoices when the customer\'s VAT number is valid. A different "Reverse charge" text might be required depending on the store\'s country.' => 'הגדר את שיעור המס לאפס והצג &quot;חיוב הפוך&quot; בחשבוניות כאשר מספר המע&quot;מ של הלקוח תקף. ייתכן שיידרש טקסט &quot;חיוב הפוך&quot; שונה בהתאם למדינת החנות.','Same country' => 'אותה מדינה','Apply reverse charge mechanism for transactions in the shop country:' => 'החל מנגנון חיוב הפוך עבור עסקאות במדינת החנות:','Enables applying reverse charge mechanism for transactions between companies in the same country as the shop.' => 'מאפשר החלת מנגנון חיוב הפוך עבור עסקאות בין חברות באותה מדינה כמו החנות.','Reverse charge exceptions' => 'חריגים לחיוב הפוך','Select additional countries to skip applying the reverse charge mechanism.' => 'בחר מדינות נוספות כדי לדלג על החלת מנגנון החיוב ההפוך.','Taxes will be charged to orders from these countries even when a valid VAT number is provided.' => 'מיסים יחויבו על הזמנות ממדינות אלה גם כאשר סופק מספר מע&quot;מ תקף.','Reverse charge label on invoices' => 'תווית חיוב הפוך על חשבוניות','Set the label of "reverse charge" on the checkout page and order details.' => 'הגדר את התווית &quot;חיוב הפוך&quot; בדף התשלום ובפרטי ההזמנה.','Reverse charge text on invoices' => 'טקסט חיוב הפוך בחשבוניות','Set the label of "reverse charge" text on invoices.' => 'הגדר את התווית של טקסט &quot;חיוב הפוך&quot; בחשבוניות.','Tax to be paid on reverse charge basis' => 'מס שיש לשלם על בסיס חיוב הפוך','Company name' => 'שם החברה','Autocomplete company name from VAT number' => 'השלמה אוטומטית של שם החברה ממספר מע&quot;מ','Fill in the billing company name based on the valid VAT number provided by the customer.' => 'מלא את שם חברת החיוב בהתבסס על מספר מע&quot;מ תקף שסופק על ידי הלקוח.','Company name editing' => 'עריכת שם החברה','Allow editing of auto-filled company name' => 'אפשר עריכה של שם חברה שמולא אוטומטית','When enabled, customers can change the company name associated with the provided VAT number.' => 'כאשר אפשרות זו מופעלת, לקוחות יכולים לשנות את שם החברה המשויך למספר המע&quot;מ שסופק.','EU-VAT for digital goods' => 'מע&quot;מ של האיחוד האירופי עבור מוצרים דיגיטליים','From January 1st, 2015, modifications have been made to the EU VAT regulations concerning digital goods, impacting exclusively B2C transactions. The VAT on digital goods must be calculated based on the customer\'s location, and evidence of this needs to be collected (IP address and billing address).' => 'החל מ-1 בינואר 2015, בוצעו שינויים בתקנות המע&quot;מ של האיחוד האירופי בנוגע למוצרים דיגיטליים, המשפיעים אך ורק על עסקאות B2C. יש לחשב את המע&quot;מ על מוצרים דיגיטליים על סמך מיקום הלקוח, ויש לאסוף ראיות לכך (כתובת IP וכתובת לחיוב).','Tax classes for digital goods' => 'שיעורי מס עבור מוצרים דיגיטליים','Select some tax classes' => 'בחר כמה מחלקות מס','Location evidence' => 'ראיות מיקום','Collect customer\'s location evidence' => 'איסוף ראיות למיקום הלקוח','Saves the IP address and validate it against the customer\'s billing address. Customer\'s must confirm their billing address by checking a checkbox on the checkout page if the country from their billing address and IP do not match.' => 'שומר את כתובת ה-IP ומאמת אותה מול כתובת החיוב של הלקוח. על הלקוח לאשר את כתובת החיוב שלו על ידי סימון תיבת סימון בדף התשלום אם המדינה מכתובת החיוב וכתובת ה-IP שלו אינן תואמות.','This option is managed in Fluid Checkout. <a href="%s">Change it in Customer accounts settings</a>.' => 'אפשרות זו מנוהלת ב-Fluid Checkout. <a href="%s">ניתן לשנות אותה בהגדרות חשבונות הלקוח</a> .','This option is managed in Fluid Checkout. Change it under Fluid Checkout > Customer accounts.' => 'אפשרות זו מנוהלת ב-Fluid Checkout. ניתן לשנות אותה תחת Fluid Checkout &gt; חשבונות לקוחות.','This option is managed in Fluid Checkout. The shipping destination is always set to "Default to customer shipping address" when Fluid Checkout is activated. Customers can still provide different shipping and billing addresses during checkout.<br><br>An option for setting the default billing address to be the same as the shipping address is available in the <a href="%s">Fluid Checkout settings</a>.' => 'אפשרות זו מנוהלת ב-Fluid Checkout. יעד המשלוח תמיד מוגדר כ&quot;ברירת מחדל לכתובת המשלוח של הלקוח&quot; כאשר Fluid Checkout מופעל. לקוחות עדיין יכולים לספק כתובות משלוח וכתובות חיוב שונות במהלך התשלום.<br><br> אפשרות להגדרת כתובת ברירת המחדל לחיוב כך שתהיה זהה לכתובת המשלוח זמינה <a href="%s">בהגדרות Fluid Checkout</a> .','This option is managed in Fluid Checkout. The shipping destination is always set to "Default to customer shipping address" when Fluid Checkout is activated. Customers can still provide different shipping and billing addresses during checkout.<br><br>An option for setting the default billing address to be the same as the shipping address is available at WooCommerce > Settings > Fluid Checkout.' => 'אפשרות זו מנוהלת ב-Fluid Checkout. יעד המשלוח תמיד מוגדר כ&quot;ברירת מחדל לכתובת המשלוח של הלקוח&quot; כאשר Fluid Checkout מופעל. לקוחות עדיין יכולים לספק כתובות משלוח וכתובות חיוב שונות במהלך התשלום.<br><br> אפשרות להגדרת כתובת ברירת המחדל לחיוב כך שתהיה זהה לכתובת המשלוח זמינה ב-WooCommerce &gt; הגדרות &gt; Fluid Checkout.','These settings have been moved to WP Admin > Fluid Checkout > Settings.' => 'הגדרות אלו הועברו אל WP Admin &gt; Fluid Checkout &gt; הגדרות.','This WooCommerce Settings tab is deprecated and will be removed in Fluid Checkout 6.0.' => 'לשונית הגדרות WooCommerce זו הוצאה משימוש ותוסר ב-Fluid Checkout 6.0.','Go to settings page' => 'עבור לדף ההגדרות','Hide this tab permanently' => 'הסתר את הכרטיסייה הזו לצמיתות','Site report preview' => 'תצוגה מקדימה של דוח האתר','This is the data that would be included in the next site environment report based on your current settings.' => 'אלו הנתונים שייכללו בדוח סביבת האתר הבא בהתבסס על ההגדרות הנוכחיות שלך.','Loading report preview...' => 'טוען תצוגה מקדימה של הדוח...','Could not load the site report preview. Try again.' => 'לא ניתן היה לטעון את התצוגה המקדימה של דוח האתר. נסה שוב.','Could not send the site report. Try again.' => 'לא ניתן היה לשלוח את דוח האתר. נסה שוב.','Site report sent successfully.' => 'דוח האתר נשלח בהצלחה.','Enable and send now' => 'הפעל ושלח עכשיו','Close' => 'לִסְגוֹר','A site report request is already in progress. Try again in a moment.' => 'בקשת דוח אתר כבר נמצאת בתהליך. נסה שוב בעוד רגע.','Site environment reporting is disabled.' => 'דיווח סביבת האתר מושבת.','No site report data is available to send.' => 'אין נתוני דוח אתר זמינים לשליחה.','This site domain cannot send environment reports (local or development domains are excluded).' => 'דומיין אתר זה אינו יכול לשלוח דוחות סביבה (דומיינים מקומיים או דומיינים לפיתוח אינם כלולים).','A site report was sent recently. Try again later.' => 'דוח אתר נשלח לאחרונה. נסה שוב מאוחר יותר.','The site report could not be sent. Try again later.' => 'לא ניתן היה לשלוח את דוח האתר. נסה שוב מאוחר יותר.','Site environment reporting is not available.' => 'דיווח על סביבת האתר אינו זמין.','No site report data is available for the selected settings.' => 'אין נתוני דוח אתר זמינים עבור ההגדרות שנבחרו.','You are not allowed to manage site reports.' => 'אינך רשאי לנהל דוחות אתר.','PRO feature' => 'תכונת PRO','Other plugins' => 'תוספים אחרים','Get only this add-on &mdash; %s' => 'קבל רק את התוסף הזה — %s','Install add-on' => 'התקנת תוסף','Upgrade to PRO &mdash; %s' => 'שדרגו ל-PRO — %s','<a target="_blank" href="%1$s">Get %2$s</a> to unlock these options.' => '<a target="_blank" href="%1$s">קבל %2$s</a> כדי לפתוח את האפשרויות האלה.','Add-on' => 'תוסף','View documentation' => 'הצג תיעוד','Requests require a logged-in WordPress user. Omit user_id to use the current user\'s data, or pass user_id to target another account when the caller can edit that user (edit_user capability). Unauthenticated requests return fc_api_forbidden. An invalid user_id returns fc_api_user_not_found.' => 'בקשות דורשות משתמש וורדפרס מחובר. יש להשמיט את הפונקציה user_id כדי להשתמש בנתוני המשתמש הנוכחי, או להעביר את הפונקציה user_id לחשבון אחר כאשר המתקשר יכול לערוך משתמש זה (יכולת edit_user). בקשות לא מאומתות מחזירות את הפונקציה fc_api_forbidden. user_id לא חוקי מחזיר את הפונקציה fc_api_user_not_found.','HTTP 200 with { "data": { ... } } when the handler returns a payload.' => 'HTTP 200 עם { &quot;data&quot;: { ... } } כאשר המטפל מחזיר מטען.','HTTP 200 with { "success": true } when there is no payload (for example DELETE).' => 'HTTP 200 עם { &quot;success&quot;: true } כאשר אין מטען (לדוגמה DELETE).','Failures return WordPress REST error JSON from WP_Error (code, message, data.status). Wire codes use the fc_api_* prefix.' => 'כשלים מחזירים שגיאת REST של וורדפרס בקובץ JSON מ-WP_Error (code, message, data.status). קודי Wire משתמשים בקידומת fc_api_*.','Forbidden access.' => 'גישה אסורה.','Target user was not found.' => 'משתמש היעד לא נמצא.','This feature is not available.' => 'תכונה זו אינה זמינה.','A required address field is missing.' => 'חסר שדה כתובת חובה.','Postcode or ZIP is invalid.' => 'מיקוד או קוד ZIP אינם חוקיים','Phone number is invalid.' => 'מספר הטלפון אינו תקין.','State or county is invalid.' => 'מדינה או מחוז אינם חוקיים.','Country is invalid or has no address fields.' => 'המדינה אינה חוקית או שאין בה שדות כתובת.','The request could not be processed.' => 'לא ניתן היה לעבד את הבקשה.','Back to previous step' => 'חזרה לשלב הקודם','Skip to settings' => 'דלג להגדרות','Start over and return to the first guided setup step' => 'התחל מחדש וחזר לשלב ההתקנה המודרך הראשון','Start over' => 'התחל מחדש','Please complete all sub-steps before continuing.' => 'אנא השלם את כל תתי השלבים לפני שתמשיך.','Expand' => 'לְהַרְחִיב','Collapse' => 'הִתמוֹטְטוּת','Skip' => 'לְדַלֵג','Mark as complete' => 'סמן כשלם','Mark as incomplete' => 'סמן כלא גמור','View full-size image: %s' => 'הצג תמונה בגודל מלא: %s','Full-size setup guide image' => 'תמונה של מדריך ההתקנה בגודל מלא','Close image' => 'סגור תמונה','Fluid Checkout Guided Setup' => 'הגדרה מודרכת של Fluid Checkout','Welcome' => 'קַבָּלַת פָּנִים','Explore your checkout' => 'סקירת התשלום שלך','All set' => 'מוּכָן','You do not have permission to access this page.' => 'אין לך הרשאה לגשת לדף זה.','Go to step %1$d: %2$s' => 'עבור לשלב %1$d: %2$s','This guided setup helps you get familiar with Fluid Checkout. The steps below are placeholders for now.' => 'מדריך זה להגדרה עוזר לך להכיר את Fluid Checkout. השלבים הבאים הם כרגע מצייני מיקום.','Continue to the next step when you are ready.' => 'המשך לשלב הבא כשתהיה מוכן.','Open your store checkout to see Fluid Checkout in action.' => 'פתחו את קופה החנות שלכם כדי לראות את Fluid Checkout בפעולה.','View checkout page' => 'צפה בדף התשלום','You can return to Fluid Checkout settings to continue configuring your store.' => 'באפשרותך לחזור להגדרות Fluid Checkout כדי להמשיך בהגדרת 